struct Entry { word: Str, n: Int }

fn bump(counts: Map<Str, Int>, cur: Bytes) -> Map<Str, Int> {
  let mut m = counts;
  if cur.len() > 0 {
    let w = cur.to_str();
    m.insert(w, m.get(w).unwrap_or(0) + 1);
  }
  m
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let data = input.read("text.txt")?;
  let mut counts: Map<Str, Int> = Map::new();
  let mut cur = "".to_bytes();
  for b in data {
    if b >= 65 && b <= 90 {
      cur.push(b + 32);
    } else if b >= 97 && b <= 122 {
      cur.push(b);
    } else {
      counts = bump(counts, cur);
      cur = "".to_bytes();
    }
  }
  counts = bump(counts, cur);
  let mut entries: List<Entry> = [];
  for k in counts.keys() {
    entries.push(Entry { word: k, n: counts.get(k).unwrap_or(0) });
  }
  entries.sort_by(|a, b| a.n > b.n || (a.n == b.n && a.word < b.word));
  let n = entries.len().min(5);
  let mut lines: List<Str> = [];
  for i in 0..n {
    lines.push(entries[i].word + " " + entries[i].n.to_str());
  }
  Ok(lines.join("\n"))
}

struct Agg { region: Str, qty: Int, cents: Int }

fn money(c: Int) -> Str {
  let neg = c < 0;
  let a = if neg { -c } else { c };
  let r = a % 100;
  let mut s = (a / 100).to_str() + ".";
  if r < 10 { s = s + "0"; }
  s = s + r.to_str();
  if neg { "-" + s } else { s }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let mut qty: Map<Str, Int> = Map::new();
  let mut cents: Map<Str, Int> = Map::new();
  let mut skipped = 0;
  let mut first = true;
  for line in text.lines() {
    if first {
      first = false;
      continue;
    }
    if line.trim() == "" { continue; }
    let parts = line.split(",");
    if parts.len() != 5 {
      skipped += 1;
      continue;
    }
    let region = parts[1].trim();
    let Some(q) = parts[3].trim().parse_int() else {
      skipped += 1;
      continue;
    };
    let Some(u) = parts[4].trim().parse_int() else {
      skipped += 1;
      continue;
    };
    let oq = qty.get(region).unwrap_or(0);
    let oc = cents.get(region).unwrap_or(0);
    qty.insert(region, oq + q);
    cents.insert(region, oc + q * u);
  }
  let mut rows: List<Agg> = [];
  for r in qty.keys() {
    rows.push(Agg { region: r, qty: qty.get(r).unwrap_or(0), cents: cents.get(r).unwrap_or(0) });
  }
  rows.sort_by(|a, b| a.cents > b.cents || (a.cents == b.cents && a.region < b.region));
  let mut out = "";
  for r in rows {
    out = out + r.region + " " + r.qty.to_str() + " " + money(r.cents) + "\n";
  }
  out = out + "skipped " + skipped.to_str() + "\n";
  Ok(out)
}

struct Entry { ip: Str, status: Int, size: Int, path: Str }
struct ErrRow { ip: Str, n: Int }

fn parse_line(line: Str) -> Option<Entry> {
  let Some(q) = line.find("\"") else { return None; };
  let rest = line.slice(q + 1, line.len());
  let Some(q2) = rest.find("\"") else { return None; };
  let req = rest.slice(0, q2);
  let after = rest.slice(q2 + 1, rest.len()).trim();
  let fields = after.split(" ");
  if fields.len() != 2 { return None; }
  let Some(status) = fields[0].parse_int() else { return None; };
  let mut size = 0;
  if fields[1] != "-" {
    let Some(s) = fields[1].parse_int() else { return None; };
    size = s;
  }
  let head = line.slice(0, q).trim();
  let hp = head.split(" ");
  if hp.len() == 0 || hp[0].len() == 0 { return None; }
  let words = req.split(" ");
  if words.len() < 2 { return None; }
  let mut path = words[1];
  if let Some(i) = path.find("?") {
    path = path.slice(0, i);
  }
  Some(Entry { ip: hp[0], status: status, size: size, path: path })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errs: Map<Str, Int> = Map::new();
  let mut total = 0;
  for line in text.lines() {
    let Some(e) = parse_line(line) else { continue; };
    statuses.insert(e.status, statuses.get(e.status).unwrap_or(0) + 1);
    total = total + e.size;
    paths.insert(e.path, paths.get(e.path).unwrap_or(0) + 1);
    if e.status >= 500 && e.status <= 599 {
      errs.insert(e.ip, errs.get(e.ip).unwrap_or(0) + 1);
    }
  }
  let mut out = "";
  for k in statuses.keys() {
    out = out + k.to_str() + " " + statuses.get(k).unwrap_or(0).to_str() + "\n";
  }
  out = out + "bytes " + total.to_str() + "\n";
  let mut best = "";
  let mut bestn = 0;
  for p in paths.keys() {
    let c = paths.get(p).unwrap_or(0);
    if c > bestn {
      bestn = c;
      best = p;
    }
  }
  if bestn > 0 {
    out = out + "top " + best + " " + bestn.to_str() + "\n";
  }
  let mut rows: List<ErrRow> = [];
  for ip in errs.keys() {
    rows.push(ErrRow { ip: ip, n: errs.get(ip).unwrap_or(0) });
  }
  rows.sort_by(|a: ErrRow, b: ErrRow| if a.n != b.n { a.n > b.n } else { a.ip < b.ip });
  for r in rows {
    out = out + "errors " + r.ip + " " + r.n.to_str() + "\n";
  }
  Ok(out)
}

fn order_total(o: Json) -> Int {
  let items = o.get("items").and_then(|j| j.as_list()).unwrap_or([]);
  let mut t = 0;
  for it in items {
    let q = it.get("qty").and_then(|j| j.as_int()).unwrap_or(0);
    let p = it.get("price_cents").and_then(|j| j.as_int()).unwrap_or(0);
    t += q * p;
  }
  t
}

fn main(input: Dir) -> Result<Str, Str> {
  let bytes = match input.read("orders.json") {
    Ok(b) => b,
    Err(_) => return Err("cannot read orders.json"),
  };
  let doc = match bytes.to_str().parse_json() {
    Ok(j) => j,
    Err(e) => return Err(e),
  };
  let orders = doc.as_list().unwrap_or([]);
  let mut counts: Map<Str, Int> = Map::new();
  let mut totals: Map<Str, Int> = Map::new();
  let mut ref_n = 0;
  let mut ref_t = 0;
  let mut pend = 0;
  for o in orders {
    let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
    let customer = o.get("customer").and_then(|j| j.as_str()).unwrap_or("");
    let t = order_total(o);
    if status == "paid" {
      counts.insert(customer, counts.get(customer).unwrap_or(0) + 1);
      totals.insert(customer, totals.get(customer).unwrap_or(0) + t);
    } else if status == "refunded" {
      ref_n += 1;
      ref_t += t;
    } else if status == "pending" {
      pend += 1;
    }
  }
  let mut out = "";
  for c in counts.keys() {
    out = out + c + " " + counts.get(c).unwrap_or(0).to_str() + " " + totals.get(c).unwrap_or(0).to_str() + "\n";
  }
  out = out + "refunded " + ref_n.to_str() + " " + ref_t.to_str() + "\n";
  out = out + "pending " + pend.to_str() + "\n";
  Ok(out)
}

fn normalize(line: Str) -> Option<Str> {
  let s = line.trim().to_lowercase();
  let parts = s.split("@");
  if parts.len() != 2 { return None; }
  let mut local = parts[0];
  let domain = parts[1];
  if local.len() == 0 { return None; }
  if !domain.contains(".") || domain.starts_with(".") || domain.ends_with(".") {
    return None;
  }
  if domain == "gmail.com" {
    if let Some(i) = local.find("+") {
      local = local.slice(0, i);
    }
    local = local.replace(".", "");
  }
  Some(local + "@" + domain)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("emails.txt")?.to_str();
  let mut seen: Map<Str, Bool> = Map::new();
  let mut invalid = 0;
  for line in text.lines() {
    if line.trim().len() == 0 { continue; }
    match normalize(line) {
      Some(a) => seen.insert(a, true),
      None => invalid += 1,
    }
  }
  let mut out = "";
  for k in seen.keys() {
    out = out + k + "\n";
  }
  out = out + "invalid " + invalid.to_str() + "\n";
  Ok(out)
}

fn to_roman(n: Int) -> Str {
  let vals: List<Int> = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  let syms: List<Str> = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
  let mut r = "";
  let mut m = n;
  let mut i = 0;
  while i < vals.len() {
    while m >= vals[i] {
      r = r + syms[i];
      m -= vals[i];
    }
    i += 1;
  }
  r
}

fn dv(c: Str) -> Int {
  match c {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0,
  }
}

fn from_roman(s: Str) -> Int {
  let chars = s.chars();
  let mut total = 0;
  let mut i = 0;
  while i < chars.len() {
    let v = dv(chars[i]);
    if v == 0 { return 0; }
    if i + 1 < chars.len() && dv(chars[i + 1]) > v {
      total -= v;
    } else {
      total += v;
    }
    i += 1;
  }
  if total < 1 || total > 3999 { return 0; }
  if to_roman(total) != s { return 0; }
  total
}

fn convert(line: Str) -> Str {
  let mut all_digits = true;
  for c in line.chars() {
    if !"0123456789".contains(c) { all_digits = false; }
  }
  if all_digits {
    let Some(n) = line.parse_int() else { return "invalid"; };
    if n < 1 || n > 3999 { return "invalid"; }
    return to_roman(n);
  }
  let v = from_roman(line);
  if v == 0 { return "invalid"; }
  v.to_str()
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("numbers.txt")?.to_str();
  let mut out: List<Str> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 { continue; }
    out.push(line + " = " + convert(line));
  }
  Ok(out.join("\n"))
}

fn check(line: Str) -> Str {
  let mut stack: List<Str> = [];
  let cs = line.chars();
  let mut i = 0;
  while i < cs.len() {
    let c = cs[i];
    if c == "(" {
      stack.push(")");
    } else if c == "[" {
      stack.push("]");
    } else if c == "{" {
      stack.push("}");
    } else if c == ")" || c == "]" || c == "}" {
      match stack.pop() {
        None => {
          return "col " + (i + 1).to_str() + ": unexpected " + c;
        }
        Some(x) => {
          if x != c {
            return "col " + (i + 1).to_str() + ": expected " + x + ", found " + c;
          }
        }
      }
    }
    i += 1;
  }
  if stack.len() > 0 {
    return "unclosed " + stack[stack.len() - 1];
  }
  "ok"
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("snippets.txt")?.to_str();
  let mut out: List<Str> = [];
  for line in text.lines() {
    out.push(check(line));
  }
  Ok(out.join("\n"))
}

struct E { key: Str, ms: Int }

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("timings.log")?.to_str();
  let mut es: List<E> = [];
  for line in text.lines() {
    let parts = line.trim().split(" ");
    if parts.len() != 3 { continue; }
    let Some(ms) = parts[2].parse_int() else { continue; };
    es.push(E { key: parts[0] + " " + parts[1], ms: ms });
  }
  es.sort_by(|a, b| a.key < b.key || (a.key == b.key && a.ms < b.ms));
  let mut out: List<Str> = [];
  let total = es.len();
  let mut i = 0;
  while i < total {
    let mut j = i;
    while j < total && es[j].key == es[i].key { j += 1; }
    let n = j - i;
    let p50 = es[i + (50 * n + 99) / 100 - 1].ms;
    let p95 = es[i + (95 * n + 99) / 100 - 1].ms;
    let mx = es[j - 1].ms;
    out.push(es[i].key + " count=" + n.to_str() + " p50=" + p50.to_str() + " p95=" + p95.to_str() + " max=" + mx.to_str());
    i = j;
  }
  Ok(out.join("\n"))
}

struct Adj { to: Int, w: Int }
struct Trip { a: Str, b: Str }

fn dijkstra(adj: List<List<Adj>>, src: Int) -> List<Int> {
  let n = adj.len();
  let mut dist: List<Int> = [];
  let mut done: List<Bool> = [];
  for i in 0..n {
    dist.push(-1);
    done.push(false);
  }
  dist[src] = 0;
  loop {
    let mut best = -1;
    for i in 0..n {
      if !done[i] && dist[i] >= 0 && (best < 0 || dist[i] < dist[best]) {
        best = i;
      }
    }
    if best < 0 { break; }
    done[best] = true;
    for e in adj[best] {
      let nd = dist[best] + e.w;
      if dist[e.to] < 0 || nd < dist[e.to] {
        dist[e.to] = nd;
      }
    }
  }
  dist
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("routes.txt")?.to_str();
  let mut ids: Map<Str, Int> = Map::new();
  let mut names: List<Str> = [];
  let mut adj: List<List<Adj>> = [];
  let mut trips: List<Trip> = [];
  let mut roads: List<List<Str>> = [];
  for raw in text.lines() {
    let line = raw.replace("\t", " ").trim();
    if line.len() == 0 || line.starts_with("#") { continue; }
    let p = line.split(" ").filter(|s| s.len() > 0);
    if p.len() >= 4 && p[0] == "road" {
      roads.push(p);
    } else if p.len() >= 3 && p[0] == "trip" {
      trips.push(Trip { a: p[1], b: p[2] });
    }
  }
  for p in roads {
    let Some(w) = p[3].parse_int() else { continue; };
    for name in [p[1], p[2]] {
      if ids.get(name).is_none() {
        ids.insert(name, names.len());
        names.push(name);
        let empty: List<Adj> = [];
        adj.push(empty);
      }
    }
    let a = ids.get(p[1]).unwrap_or(0);
    let b = ids.get(p[2]).unwrap_or(0);
    adj[a].push(Adj { to: b, w: w });
    adj[b].push(Adj { to: a, w: w });
  }
  let mut cache: HashMap<Int, List<Int>> = HashMap::new();
  let mut out: List<Str> = [];
  for t in trips {
    if t.a == t.b {
      out.push(t.a + " 0");
      continue;
    }
    let Some(s) = ids.get(t.a) else {
      out.push(t.a + " " + t.b + " unreachable");
      continue;
    };
    let Some(g) = ids.get(t.b) else {
      out.push(t.a + " " + t.b + " unreachable");
      continue;
    };
    let dist: List<Int> = match cache.get(g) {
      Some(d) => d,
      None => {
        let d = dijkstra(adj, g);
        cache.insert(g, d);
        d
      }
    };
    if dist[s] < 0 {
      out.push(t.a + " " + t.b + " unreachable");
      continue;
    }
    let mut path: List<Str> = [names[s]];
    let mut cur = s;
    while cur != g {
      let mut next = -1;
      for e in adj[cur] {
        if dist[e.to] >= 0 && e.w + dist[e.to] == dist[cur] {
          if next < 0 || names[e.to] < names[next] {
            next = e.to;
          }
        }
      }
      if next < 0 { break; }
      cur = next;
      path.push(names[cur]);
    }
    out.push(path.join(" -> ") + " " + dist[s].to_str());
  }
  Ok(out.join("\n"))
}

struct Leaf { path: Str, line: Str }

fn merge(base: Json, over: Json) -> Json {
  match base {
    Json::Obj(bm) => match over {
      Json::Obj(om) => {
        let mut r = bm;
        for k in om.keys() {
          let Some(v) = om.get(k) else { continue; };
          if v == Json::Null {
            r.remove(k);
            continue;
          }
          let merged = match r.get(k) {
            Some(b) => merge(b, v),
            None => v,
          };
          r.insert(k, merged);
        }
        Json::Obj(r)
      }
      _ => over,
    },
    _ => over,
  }
}

fn child(path: Str, k: Str) -> Str {
  if path == "" { k } else { path + "." + k }
}

fn flatten(j: Json, path: Str) -> List<Leaf> {
  let mut res: List<Leaf> = [];
  match j {
    Json::Obj(m) => {
      if m.len() == 0 {
        res.push(Leaf { path: path, line: path + "={}" });
      } else {
        for k in m.keys() {
          let Some(v) = m.get(k) else { continue; };
          for l in flatten(v, child(path, k)) { res.push(l); }
        }
      }
    }
    Json::Arr(a) => {
      if a.len() == 0 {
        res.push(Leaf { path: path, line: path + "=[]" });
      } else {
        let mut i = 0;
        for v in a {
          for l in flatten(v, child(path, i.to_str())) { res.push(l); }
          i += 1;
        }
      }
    }
    other => {
      res.push(Leaf { path: path, line: path + "=" + other.to_json() });
    }
  }
  res
}

fn main(input: Dir) -> Result<Str, Str> {
  let b = input.read("base.json").map_err(|e| "cannot read base.json")?.to_str();
  let o = input.read("override.json").map_err(|e| "cannot read override.json")?.to_str();
  let base = b.parse_json()?;
  let over = o.parse_json()?;
  let merged = merge(base, over);
  let mut leaves = flatten(merged, "");
  leaves.sort_by_key(|l| l.path);
  let lines = leaves.map(|l| l.line);
  Ok(lines.join("\n"))
}

fn join_lines(xs: List<Str>) -> Str {
  if xs.len() == 0 {
    "".to_str()
  } else {
    xs.join("\n") + "\n"
  }
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("app.log")?.to_str();
  let mut errs: List<Str> = [];
  let mut warns: List<Str> = [];
  let mut infos: List<Str> = [];
  let mut other = 0;
  for line in text.lines() {
    if line.trim().len() == 0 {
      continue;
    }
    let parts = line.split(" ");
    if parts.len() < 3 {
      other += 1;
      continue;
    }
    let lv = parts[1].to_uppercase();
    match lv {
      "ERROR" => { errs.push(line); }
      "WARN" | "WARNING" => { warns.push(line); }
      "INFO" => { infos.push(line); }
      _ => { other += 1; }
    }
  }
  out.write("error.log", join_lines(errs).to_bytes())?;
  out.write("warn.log", join_lines(warns).to_bytes())?;
  out.write("info.log", join_lines(infos).to_bytes())?;
  Ok("error " + errs.len().to_str() + "\nwarn " + warns.len().to_str() + "\ninfo " + infos.len().to_str() + "\nother " + other.to_str())
}

