  out.write("info.log", join_lines(infos).to_bytes())?;
  Ok("error " + errs.len().to_str() + "\nwarn " + warns.len().to_str() + "\ninfo " + infos.len().to_str() + "\nother " + other.to_str())
}

struct Entry { path: Str, bytes: Int, lines: Int }

fn walk(d: Dir, prefix: Str, rows: List<Entry>) -> Result<List<Entry>, IoErr> {
  let mut acc = rows;
  let dir = if prefix == "" { "" } else { prefix.slice(0, prefix.len() - 1) };
  let names = d.list(dir)?;
  for name in names {
    let full = prefix + name;
    if name.ends_with("/") {
      acc = walk(d, full, acc)?;
    } else {
      let data = d.read(full)?;
      let mut n = 0;
      let mut last = 0;
      for b in data {
        if b == 10 { n += 1; }
        last = b;
      }
      if data.len() > 0 && last != 10 { n += 1; }
      acc.push(Entry { path: full, bytes: data.len(), lines: n });
    }
  }
  Ok(acc)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let empty: List<Entry> = [];
  let mut rows = walk(input, "", empty)?;
  rows.sort_by_key(|e| e.path);
  let mut text = "path,bytes,lines\n";
  let mut total = 0;
  for r in rows {
    text = text + r.path + "," + r.bytes.to_str() + "," + r.lines.to_str() + "\n";
    total += r.bytes;
  }
  out.write("index.csv", text.to_bytes())?;
  Ok("files " + rows.len().to_str() + " bytes " + total.to_str())
}

fn parse_line(line: Str) -> List<Str> {
  let cs = line.chars();
  let mut fields: List<Str> = [];
  let mut cur = "";
  let mut inq = false;
  let mut i = 0;
  while i < cs.len() {
    let c = cs[i];
    if inq {
      if c == "\"" {
        if i + 1 < cs.len() && cs[i + 1] == "\"" {
          cur = cur + "\"";
          i += 1;
        } else {
          inq = false;
        }
      } else {
        cur = cur + c;
      }
    } else {
      if c == "\"" {
        inq = true;
      } else if c == "," {
        fields.push(cur);
        cur = "";
      } else {
        cur = cur + c;
      }
    }
    i += 1;
  }
  fields.push(cur);
  fields
}

fn is_active(s: Str) -> Bool {
  match s.trim().to_lowercase() {
    "yes" | "true" | "1" => true,
    _ => false,
  }
}

fn make_row(f: List<Str>) -> Option<Json> {
  if f.len() != 5 { return None; }
  let id = f[0].trim().parse_int()?;
  let mut tags: List<Json> = [];
  for t in f[4].split(";") {
    let tt = t.trim();
    if tt.len() > 0 { tags.push(Json::Str(tt)); }
  }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(id));
  m.insert("name", Json::Str(f[1]));
  m.insert("email", Json::Str(f[2]));
  m.insert("active", Json::Bool(is_active(f[3])));
  m.insert("tags", Json::Arr(tags));
  Some(Json::Obj(m))
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("users.csv")?.to_str();
  let mut items: List<Json> = [];
  let mut skipped = 0;
  let mut first = true;
  for line in text.lines() {
    if first {
      first = false;
      continue;
    }
    if line.trim().len() == 0 { continue; }
    match make_row(parse_line(line)) {
      Some(j) => items.push(j),
      None => skipped += 1,
    }
  }
  let n = items.len();
  out.write("users.json", Json::Arr(items).to_json().to_bytes())?;
  Ok("rows " + n.to_str() + " skipped " + skipped.to_str())
}

fn norm(name: Str) -> Str {
  let mut o = "".to_bytes();
  let mut last = false;
  for b in name.to_bytes() {
    let c = if b >= 65 && b <= 90 { b + 32 } else { b };
    if (c >= 97 && c <= 122) || (c >= 48 && c <= 57) || c == 46 {
      o.push(c);
      last = false;
    } else if !last {
      o.push(45);
      last = true;
    }
  }
  let n = o.len();
  let mut s = 0;
  while s < n && o[s] == 45 { s += 1; }
  let mut e = n;
  while e > s && o[e - 1] == 45 { e -= 1; }
  o.slice(s, e).to_str()
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let names = input.list("")?;
  let mut taken: Map<Str, Bool> = Map::new();
  let mut lines: List<Str> = [];
  for name in names {
    let nn = norm(name);
    if nn.len() == 0 || taken.get(nn).is_some() {
      lines.push(name + " skipped");
    } else {
      let data = input.read(name)?;
      out.create(nn, data)?;
      taken.insert(nn, true);
      lines.push(name + " -> " + nn);
    }
  }
  Ok(lines.join("\n"))
}

fn is_part(name: Str) -> Bool {
  let Some(rest) = name.strip_prefix("part-") else { return false; };
  let Some(mid) = rest.strip_suffix(".txt") else { return false; };
  let cs = mid.chars();
  if cs.len() != 4 { return false; }
  for c in cs {
    if !"0123456789".contains(c) { return false; }
  }
  true
}

fn parse_part(text: Str) -> Option<List<Int>> {
  let mut vals: List<Int> = [];
  for line in text.lines() {
    let t = line.trim();
    if t.len() == 0 { continue; }
    match t.parse_int() {
      Some(v) => vals.push(v),
      None => return None,
    }
  }
  Some(vals)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let names = input.list("")?;
  let mut parts = 0;
  let mut corrupt = 0;
  let mut all: List<Int> = [];
  for name in names {
    if !is_part(name) { continue; }
    parts += 1;
    match input.read(name) {
      Err(_) => corrupt += 1,
      Ok(b) => {
        match parse_part(b.to_str()) {
          None => corrupt += 1,
          Some(vs) => {
            for v in vs { all.push(v); }
          }
        }
      }
    }
  }
  all.sort();
  let mut uniq: List<Int> = [];
  for x in all {
    if uniq.len() == 0 || uniq[uniq.len() - 1] != x {
      uniq.push(x);
    }
  }
  let strs = uniq.map(|x| x.to_str());
  let mut text = strs.join("\n");
  if uniq.len() > 0 { text = text + "\n"; }
  out.create("merged.txt", text.to_bytes())?;
  Ok("parts " + parts.to_str() + " corrupt " + corrupt.to_str() + " values " + uniq.len().to_str())
}

fn main(src: Dir, dst: Dir) -> Result<Str, IoErr> {
  let snames = src.list("")?;
  let dnames = dst.list("")?;
  let mut out = "";
  for n in snames {
    let data = src.read(n)?;
    if dnames.contains(n) {
      let old = dst.read(n)?;
      if old == data {
        out = out + "same " + n + "\n";
      } else {
        dst.write(n, data)?;
        out = out + "updated " + n + "\n";
      }
    } else {
      dst.write(n, data)?;
      out = out + "added " + n + "\n";
    }
  }
  let mut kept = 0;
  for n in dnames {
    if !snames.contains(n) {
      kept += 1;
    }
  }
  out = out + "kept " + kept.to_str() + "\n";
  Ok(out)
}

struct Row { page: Str, total: Int }

fn kv_err(e: KvErr) -> Str {
  match e {
    KvErr::TooLarge => "kv: too large",
    KvErr::Full => "kv: full",
    KvErr::NotInt => "kv: not an int",
    KvErr::Overflow => "kv: overflow",
  }
}

fn run(input: Dir, counts: Kv) -> Result<Str, Str> {
  let bytes = match input.read("visits.txt") {
    Ok(b) => b,
    Err(_) => return Err("cannot read visits.txt"),
  };
  let text = bytes.to_str();
  let mut tally: Map<Str, Int> = Map::new();
  for line in text.lines() {
    let p = line.trim();
    if p.len() == 0 { continue; }
    let c = tally.get(p).unwrap_or(0);
    tally.insert(p, c + 1);
  }
  for p in tally.keys() {
    let n = tally.get(p).unwrap_or(0);
    match counts.add("p:" + p, n) {
      Ok(_) => {},
      Err(e) => return Err(kv_err(e)),
    }
  }
  let ks = match counts.keys("p:") {
    Ok(k) => k,
    Err(e) => return Err(kv_err(e)),
  };
  let mut rows: List<Row> = [];
  for k in ks {
    let total = match counts.get(k) {
      Ok(Some(b)) => b.to_str().parse_int().unwrap_or(0),
      Ok(None) => 0,
      Err(e) => return Err(kv_err(e)),
    };
    rows.push(Row { page: k.slice(2, k.len()), total: total });
  }
  rows.sort_by(|a, b| a.total > b.total || (a.total == b.total && a.page < b.page));
  let mut lines: List<Str> = [];
  for r in rows {
    lines.push(r.page + " " + r.total.to_str());
  }
  Ok(lines.join("\n"))
}

fn main(input: Dir, counts: Kv) -> Result<Str, Str> {
  run(input, counts)
}

fn run(users: Kv, line: Str) -> Result<Str, KvErr> {
  let parts = line.split(" ").filter(|p| p.len() > 0);
  let n = parts.len();
  let cmd = parts[0];
  if cmd == "put" && n == 4 {
    let id = parts[1];
    users.set("user:" + id, (parts[2] + " " + parts[3]).to_bytes())?;
    return Ok("ok " + id);
  }
  if cmd == "rename" && n == 3 {
    let id = parts[1];
    let key = "user:" + id;
    return match users.get(key)? {
      None => Ok("missing " + id),
      Some(b) => {
        let f = b.to_str().split(" ");
        users.set(key, (parts[2] + " " + f[1]).to_bytes())?;
        Ok("ok " + id)
      }
    };
  }
  if cmd == "get" && n == 2 {
    let id = parts[1];
    return match users.get("user:" + id)? {
      None => Ok("missing " + id),
      Some(b) => {
        let f = b.to_str().split(" ");
        Ok("{\"id\":" + Json::Str(id).to_json() + ",\"name\":" + Json::Str(f[0]).to_json() + ",\"email\":" + Json::Str(f[1]).to_json() + "}")
      }
    };
  }
  if cmd == "del" && n == 2 {
    let id = parts[1];
    let key = "user:" + id;
    return match users.get(key)? {
      None => Ok("missing " + id),
      Some(_) => {
        users.delete(key)?;
        Ok("ok " + id)
      }
    };
  }
  if cmd == "count" && n == 1 {
    let ks = users.keys("user:")?;
    return Ok("count " + ks.len().to_str());
  }
  Ok("bad " + line)
}

fn main(input: Dir, users: Kv) -> Result<Str, IoErr> {
  let text = input.read("commands.txt")?.to_str();
  let mut out = "";
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 { continue; }
    let res = match run(users, line) {
      Ok(s) => s,
      Err(_) => "error " + line,
    };
    out = out + res + "\n";
  }
  Ok(out)
}

fn kv(e: KvErr) -> Str {
  "kv error"
}

fn apply(state: Kv, line: Str) -> Result<Int, Str> {
  let Ok(j) = line.parse_json() else { return Ok(2); };
  if j.as_map().is_none() { return Ok(2); }
  let Some(id) = j.get("id").and_then(|x| x.as_str()) else { return Ok(2); };
  let Some(account) = j.get("account").and_then(|x| x.as_str()) else { return Ok(2); };
  let Some(cents) = j.get("cents").and_then(|x| x.as_int()) else { return Ok(2); };
  if id.len() > 900 || account.len() > 900 { return Ok(2); }
  let key = "seen/" + id;
  let claimed = state.swap(key, None, Some("1".to_bytes())).map_err(kv)?;
  if !claimed { return Ok(1); }
  match state.add("bal/" + account, cents) {
    Ok(_) => Ok(0),
    Err(_) => {
      let _r = state.delete(key);
      Ok(2)
    }
  }
}

fn main(input: Dir, state: Kv) -> Result<Str, Str> {
  let text = match input.read("events.jsonl") {
    Ok(b) => b.to_str(),
    Err(_) => return Err("cannot read events.jsonl"),
  };
  let mut applied = 0;
  let mut dup = 0;
  let mut rej = 0;
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 { continue; }
    let r = apply(state, line)?;
    if r == 0 { applied += 1; } else if r == 1 { dup += 1; } else { rej += 1; }
  }
  let mut out = "applied " + applied.to_str() + " duplicate " + dup.to_str() + " rejected " + rej.to_str() + "\n";
  let keys = state.keys("bal/").map_err(kv)?;
  for k in keys {
    let acct = k.strip_prefix("bal/").unwrap_or(k);
    let v = state.get(k).map_err(kv)?;
    let Some(b) = v else { continue; };
    out = out + acct + " " + b.to_str() + "\n";
  }
  Ok(out)
}

fn count(limits: Kv, key: Str) -> Result<Int, KvErr> {
  match limits.get(key)? {
    Some(b) => Ok(b.to_str().parse_int().unwrap_or(0)),
    None => Ok(0),
  }
}

fn main(input: Dir, limits: Kv) -> Result<Str, Str> {
  let bytes = match input.read("requests.txt") {
    Ok(b) => b,
    Err(_) => return Err("cannot read requests.txt"),
  };
  let text = bytes.to_str();
  let mut out = "";
  for line in text.lines() {
    let mut parts: List<Str> = [];
    for p in line.split(" ") {
      let t = p.trim();
      if t.len() > 0 { parts.push(t); }
    }
    if parts.len() != 2 { continue; }
    let Some(ts) = parts[0].parse_int() else { continue; };
    let client = parts[1];
    let key = "c:" + client + ":" + (ts / 60).to_str();
    let n = match count(limits, key) {
      Ok(n) => n,
      Err(_) => return Err("kv error"),
    };
    if n < 3 {
      if let Err(_) = limits.set(key, (n + 1).to_str().to_bytes()) {
        return Err("kv error");
      }
      out = out + ts.to_str() + " " + client + " allow\n";
    } else {
      out = out + ts.to_str() + " " + client + " deny\n";
    }
  }
  Ok(out)
}

struct Ent { name: Str, pts: Int, played: Int }

fn bump(board: Kv, name: Str, pts: Int, gp: Int) -> Result<(), Str> {
  match board.add("pts/" + name, pts) {
    Err(_) => return Err("kv error"),
    Ok(_) => {}
  }
  match board.add("gp/" + name, gp) {
    Err(_) => return Err("kv error"),
    Ok(_) => {}
  }
  Ok(())
}

fn read_int(board: Kv, key: Str) -> Result<Int, Str> {
  match board.get(key) {
    Ok(Some(b)) => Ok(b.to_str().parse_int().unwrap_or(0)),
    Ok(None) => Ok(0),
    Err(_) => Err("kv error"),
  }
}

fn less(a: Ent, b: Ent) -> Bool {
  if a.pts != b.pts { return a.pts > b.pts; }
  if a.played != b.played { return a.played < b.played; }
  a.name < b.name
}

fn main(input: Dir, board: Kv) -> Result<Str, Str> {
  let bytes = match input.read("games.txt") {
    Ok(b) => b,
    Err(_) => return Err("cannot read games.txt"),
  };
  let text = bytes.to_str();
  for line in text.lines() {
    let parts = line.trim().split(" ").filter(|s| s.len() > 0);
    if parts.len() == 2 {
      bump(board, parts[0], 3, 1)?;
      bump(board, parts[1], 0, 1)?;
    } else if parts.len() == 3 && parts[2] == "draw" {
      bump(board, parts[0], 1, 1)?;
      bump(board, parts[1], 1, 1)?;
    }
  }
  let keys = match board.keys("pts/") {
    Ok(k) => k,
    Err(_) => return Err("kv error"),
  };
  let mut ents: List<Ent> = [];
  for k in keys {
    let Some(name) = k.strip_prefix("pts/") else { continue; };
    let pts = read_int(board, k)?;
    let played = read_int(board, "gp/" + name)?;
    ents.push(Ent { name: name, pts: pts, played: played });
  }
  ents.sort_by(less);
  let mut lines: List<Str> = [];
  let n = ents.len().min(3);
  for i in 0..n {
    let e = ents[i];
    lines.push((i + 1).to_str() + ". " + e.name + " " + e.pts.to_str() + " " + e.played.to_str());
  }
  Ok(lines.join("\n"))
}

