fn main(input: Dir, shop: Db) -> Result<Str, Str> {
  match shop.exec("CREATE TABLE IF NOT EXISTS orders (order_id INTEGER PRIMARY KEY, customer TEXT NOT NULL, product TEXT NOT NULL, qty INTEGER NOT NULL, unit_cents INTEGER NOT NULL)", []) {
    Ok(_) => {},
    Err(_) => return Err("db error".to_str()),
  }
  let bytes = match input.read("orders.csv") {
    Ok(b) => b,
    Err(_) => return Err("cannot read orders.csv".to_str()),
  };
  let text = bytes.to_str();
  let mut imported = 0;
  let mut skipped = 0;
  let mut rejected = 0;
  let mut seen_header = false;
  for line in text.lines() {
    if line.trim().len() == 0 { continue; }
    if !seen_header {
      seen_header = true;
      continue;
    }
    let parts = line.split(",");
    if parts.len() != 5 {
      rejected += 1;
      continue;
    }
    let Some(id) = parts[0].trim().parse_int() else { rejected += 1; continue; };
    let Some(qty) = parts[3].trim().parse_int() else { rejected += 1; continue; };
    let Some(cents) = parts[4].trim().parse_int() else { rejected += 1; continue; };
    let params = [
      SqlValue::Int(id),
      SqlValue::Text(parts[1].trim()),
      SqlValue::Text(parts[2].trim()),
      SqlValue::Int(qty),
      SqlValue::Int(cents),
    ];
    match shop.exec("INSERT OR IGNORE INTO orders (order_id, customer, product, qty, unit_cents) VALUES (?, ?, ?, ?, ?)", params) {
      Ok(n) => {
        if n > 0 { imported += 1; } else { skipped += 1; }
      },
      Err(_) => return Err("db error".to_str()),
    }
  }
  let rows = match shop.query("SELECT product, SUM(qty * unit_cents) AS r, COUNT(*) FROM orders GROUP BY product ORDER BY r DESC, product ASC LIMIT 3", []) {
    Ok(r) => r,
    Err(_) => return Err("db error".to_str()),
  };
  let mut out = "imported " + imported.to_str() + " skipped " + skipped.to_str() + " rejected " + rejected.to_str();
  for row in rows {
    if row.len() < 3 { continue; }
    out = out + "\n" + text_of(row[0]) + " " + int_of(row[1]).to_str() + " " + int_of(row[2]).to_str();
  }
  Ok(out)
}

