struct Stat { country: Str, customers: Int, orders: Int, revenue: Int, top_name: Str, top_rev: Int }

fn int_at(r: List<SqlValue>, i: Int) -> Int {
  match r[i] {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn text_at(r: List<SqlValue>, i: Int) -> Str {
  match r[i] {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn better(a: Stat, b: Stat) -> Bool {
  a.revenue > b.revenue || (a.revenue == b.revenue && a.country < b.country)
}

fn main(shop: Db) -> Result<Str, DbErr> {
  let rows = shop.query(
    "SELECT c.country, c.id, c.name, COUNT(*), SUM(o.total_cents) FROM orders o JOIN customers c ON c.id = o.customer_id WHERE o.status = 'paid' AND o.placed >= '2026-01-01' AND o.placed < '2027-01-01' GROUP BY c.id ORDER BY c.country, c.id",
    [])?;
  let mut stats: List<Stat> = [];
  for r in rows {
    let country = text_at(r, 0);
    let name = text_at(r, 2);
    let n = int_at(r, 3);
    let rev = int_at(r, 4);
    let last = stats.pop();
    let mut cur = Stat { country: country, customers: 1, orders: n, revenue: rev, top_name: name, top_rev: rev };
    if let Some(p) = last {
      if p.country == country {
        let bigger = rev > p.top_rev;
        cur = Stat {
          customers: p.customers + 1,
          orders: p.orders + n,
          revenue: p.revenue + rev,
          top_name: if bigger { name } else { p.top_name },
          top_rev: if bigger { rev } else { p.top_rev },
          ..p
        };
      } else {
        stats.push(p);
      }
    }
    stats.push(cur);
  }
  stats.sort_by(better);
  let mut lines: List<Str> = [];
  let mut total_orders = 0;
  let mut total_rev = 0;
  for s in stats {
    total_orders += s.orders;
    total_rev += s.revenue;
    lines.push(s.country + " customers=" + s.customers.to_str() + " orders=" + s.orders.to_str() + " revenue=" + s.revenue.to_str() + " top=" + s.top_name);
  }
  lines.push("total orders=" + total_orders.to_str() + " revenue=" + total_rev.to_str());
  Ok(lines.join("\n"))
}

struct Move { sku: Str, n: Int }
struct Batch { name: Str, moves: List<Move>, bad: Bool }

fn parse_move(line: Str) -> Option<Move> {
  let parts = line.split(" ");
  if parts.len() != 2 { return None; }
  let sku = parts[0];
  let amt = parts[1];
  if sku.len() == 0 { return None; }
  let neg = amt.starts_with("-");
  let Some(rest) = (if neg { amt.strip_prefix("-") } else { amt.strip_prefix("+") }) else { return None; };
  if rest.starts_with("+") || rest.starts_with("-") { return None; }
  let Some(n) = rest.parse_int() else { return None; };
  if n <= 0 { return None; }
  if neg { Some(Move { sku: sku, n: 0 - n }) } else { Some(Move { sku: sku, n: n }) }
}

fn run(input: Dir, stock: Db) -> Result<Str, Str> {
  match stock.exec("CREATE TABLE IF NOT EXISTS stock (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)", []) {
    Ok(_) => {},
    Err(_) => return Err("db error"),
  }
  match stock.exec("CREATE TABLE IF NOT EXISTS batches (name TEXT PRIMARY KEY)", []) {
    Ok(_) => {},
    Err(_) => return Err("db error"),
  }
  let bytes = match input.read("moves.txt") {
    Ok(b) => b,
    Err(_) => return Err("cannot read moves.txt"),
  };
  let text = bytes.to_str();
  let mut batches: List<Batch> = [];
  for line0 in text.lines() {
    let line = line0.trim();
    if line == "" { continue; }
    if line.starts_with("batch ") {
      batches.push(Batch { name: line.slice(6, line.len()).trim(), moves: [], bad: false });
      continue;
    }
    if batches.len() == 0 { continue; }
    let i = batches.len() - 1;
    match parse_move(line) {
      Some(m) => { batches[i].moves.push(m); },
      None => { batches[i].bad = true; },
    }
  }

  let mut qty: Map<Str, Int> = Map::new();
  let mut applied: Map<Str, Int> = Map::new();
  let rows = match stock.query("SELECT sku, qty FROM stock", []) {
    Ok(r) => r,
    Err(_) => return Err("db error"),
  };
  for row in rows {
    let sku = match row[0] { SqlValue::Text(s) => s, _ => continue };
    let q = match row[1] { SqlValue::Int(n) => n, _ => continue };
    qty.insert(sku, q);
  }
  let rows2 = match stock.query("SELECT name FROM batches", []) {
    Ok(r) => r,
    Err(_) => return Err("db error"),
  };
  for row in rows2 {
    let name = match row[0] { SqlValue::Text(s) => s, _ => continue };
    applied.insert(name, 1);
  }

  let mut out = "";
  for b in batches {
    if applied.get(b.name).is_some() {
      out = out + b.name + " skipped\n";
      continue;
    }
    let mut work = qty;
    let mut ok = !b.bad;
    let mut touched: List<Str> = [];
    for m in b.moves {
      if !ok { break; }
      let cur = work.get(m.sku).unwrap_or(0);
      let nv = cur + m.n;
      if nv < 0 {
        ok = false;
      } else {
        work.insert(m.sku, nv);
        touched.push(m.sku);
      }
    }
    if !ok {
      out = out + b.name + " rejected\n";
      continue;
    }
    let mut sqls: List<Str> = [];
    let mut params: List<List<SqlValue>> = [];
    sqls.push("INSERT INTO batches (name) VALUES (?)");
    params.push([SqlValue::Text(b.name)]);
    for sku in touched {
      sqls.push("INSERT INTO stock (sku, qty) VALUES (?, ?) ON CONFLICT(sku) DO UPDATE SET qty = excluded.qty");
      params.push([SqlValue::Text(sku), SqlValue::Int(work.get(sku).unwrap_or(0))]);
    }
    match stock.transaction(sqls, params) {
      Ok(_) => {
        qty = work;
        applied.insert(b.name, 1);
        out = out + b.name + " applied\n";
      },
      Err(_) => return Err("db error"),
    }
  }
  for sku in qty.keys() {
    let q = qty.get(sku).unwrap_or(0);
    if q != 0 {
      out = out + sku + " " + q.to_str() + "\n";
    }
  }
  Ok(out)
}

fn main(input: Dir, stock: Db) -> Result<Str, Str> {
  run(input, stock)
}

fn text_of(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn process(crm: Db, text: Str) -> Result<Str, DbErr> {
  crm.exec("CREATE TABLE IF NOT EXISTS contacts (email TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL)", [])?;
  let mut inserted = 0;
  let mut updated = 0;
  let mut unchanged = 0;
  let mut rejected = 0;
  let mut idx = 0;
  for line in text.lines() {
    idx += 1;
    if idx == 1 { continue; }
    if line.trim().len() == 0 { continue; }
    let parts = line.split(",");
    if parts.len() != 3 {
      rejected += 1;
      continue;
    }
    let email = parts[0].trim().to_lowercase();
    let name = parts[1].trim();
    let phone = parts[2].trim();
    if !email.contains("@") {
      rejected += 1;
      continue;
    }
    let rows = crm.query("SELECT name, phone FROM contacts WHERE email = ?", [SqlValue::Text(email)])?;
    if rows.len() == 0 {
      crm.exec("INSERT INTO contacts (email, name, phone) VALUES (?, ?, ?)", [SqlValue::Text(email), SqlValue::Text(name), SqlValue::Text(phone)])?;
      inserted += 1;
    } else {
      let old_name = text_of(rows[0][0]);
      let old_phone = text_of(rows[0][1]);
      if old_name != name || old_phone != phone {
        crm.exec("UPDATE contacts SET name = ?, phone = ? WHERE email = ?", [SqlValue::Text(name), SqlValue::Text(phone), SqlValue::Text(email)])?;
        updated += 1;
      } else {
        unchanged += 1;
      }
    }
  }
  let mut out = "inserted " + inserted.to_str() + " updated " + updated.to_str() + " unchanged " + unchanged.to_str() + " rejected " + rejected.to_str() + "\n";
  let cnt = crm.query("SELECT COUNT(*) FROM contacts", [])?;
  let total = match cnt[0][0] {
    SqlValue::Int(n) => n,
    _ => 0,
  };
  out = out + "contacts " + total.to_str() + "\n";
  let missing = crm.query("SELECT email FROM contacts WHERE phone = '' ORDER BY email", [])?;
  for r in missing {
    out = out + "missing phone: " + text_of(r[0]) + "\n";
  }
  Ok(out)
}

fn main(input: Dir, crm: Db) -> Result<Str, Str> {
  let text = match input.read("contacts.csv") {
    Ok(b) => b.to_str(),
    Err(_) => return Err("cannot read contacts.csv"),
  };
  match process(crm, text) {
    Ok(s) => Ok(s),
    Err(_) => Err("database error"),
  }
}

struct Reply { status: Int, body: Str }
struct Entry { name: Str, count: Int }

fn entry_json(name: Str, count: Int) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("name", Json::Str(name));
  m.insert("count", Json::Num(count));
  Json::Obj(m)
}

fn error_reply(status: Int, msg: Str) -> Reply {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Reply { status: status, body: Json::Obj(m).to_json() }
}

fn valid_name(name: Str) -> Bool {
  let n = name.len();
  if n < 1 || n > 32 { return false; }
  for c in name.chars() {
    let ok = (c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c == "-";
    if !ok { return false; }
  }
  true
}

fn count_of(counts: Kv, name: Str) -> Result<Int, KvErr> {
  match counts.get("c/" + name)? {
    Some(b) => Ok(b.to_str().parse_int().unwrap_or(0)),
    None => Ok(0),
  }
}

fn top(counts: Kv) -> Result<Reply, KvErr> {
  let keys = counts.keys("c/")?;
  let mut entries: List<Entry> = [];
  for k in keys {
    let name = k.slice(2, k.len());
    let n = count_of(counts, name)?;
    entries.push(Entry { name: name, count: n });
  }
  entries.sort_by(|a, b| a.count > b.count || (a.count == b.count && a.name < b.name));
  let mut arr: List<Json> = [];
  let mut i = 0;
  while i < entries.len() && i < 3 {
    arr.push(entry_json(entries[i].name, entries[i].count));
    i += 1;
  }
  Ok(Reply { status: 200, body: Json::Arr(arr).to_json() })
}

fn handle(method: Str, target: Str, counts: Kv) -> Result<Reply, KvErr> {
  if method == "POST" {
    if let Some(name) = target.strip_prefix("/hit/") {
      if !valid_name(name) { return Ok(error_reply(400, "bad name")); }
      let n = counts.add("c/" + name, 1)?;
      return Ok(Reply { status: 200, body: entry_json(name, n).to_json() });
    }
  }
  if method == "GET" {
    if let Some(name) = target.strip_prefix("/count/") {
      if !valid_name(name) { return Ok(error_reply(400, "bad name")); }
      let n = count_of(counts, name)?;
      return Ok(Reply { status: 200, body: entry_json(name, n).to_json() });
    }
    if target == "/top" {
      return top(counts);
    }
  }
  Ok(error_reply(404, "not found"))
}

fn main(req: Incoming, res: Outgoing, counts: Kv) -> Result<Str, WebErr> {
  let r = match handle(req.method(), req.target(), counts) {
    Ok(r) => r,
    Err(_) => error_reply(500, "internal error"),
  };
  res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes())?;
  Ok("")
}

fn key(id: Int) -> Str {
  let mut s = id.to_str();
  while s.len() < 12 { s = "0" + s; }
  "todo/" + s
}

fn cont(x: Int) -> Bool { x >= 128 && x <= 191 }

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 {
      i += 1;
    } else if c >= 194 && c <= 223 {
      if i + 1 < n && cont(b[i + 1]) { i += 2; } else { return false; }
    } else if c >= 224 && c <= 239 {
      if i + 2 >= n { return false; }
      let lo = if c == 224 { 160 } else { 128 };
      let hi = if c == 237 { 159 } else { 191 };
      let c1 = b[i + 1];
      if c1 < lo || c1 > hi || !cont(b[i + 2]) { return false; }
      i += 3;
    } else if c >= 240 && c <= 244 {
      if i + 3 >= n { return false; }
      let lo = if c == 240 { 144 } else { 128 };
      let hi = if c == 244 { 143 } else { 191 };
      let c1 = b[i + 1];
      if c1 < lo || c1 > hi || !cont(b[i + 2]) || !cont(b[i + 3]) { return false; }
      i += 4;
    } else {
      return false;
    }
  }
  true
}

fn parse_obj(b: Bytes) -> Option<Json> {
  if !valid_utf8(b) { return None; }
  let Ok(j) = b.to_str().parse_json() else { return None; };
  if j.as_map().is_some() { Some(j) } else { None }
}

fn reply(res: Outgoing, status: Int, body: Str) -> Result<Str, WebErr> {
  if body.len() == 0 {
    res.send(status, [], [], "".to_bytes())?;
  } else {
    res.send(status, ["content-type"], ["application/json"], body.to_bytes())?;
  }
  Ok("")
}

fn errj(res: Outgoing, status: Int, msg: Str) -> Result<Str, WebErr> {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  reply(res, status, Json::Obj(m).to_json())
}

fn parse_id(s: Str) -> Option<Int> {
  let Some(n) = s.parse_int() else { return None; };
  if n >= 1 && n.to_str() == s { Some(n) } else { None }
}

fn create(res: Outgoing, store: Kv, body: Bytes) -> Result<Str, WebErr> {
  let Some(doc) = parse_obj(body) else { return errj(res, 400, "title required"); };
  let Some(raw) = doc.get("title").and_then(|j| j.as_str()) else {
    return errj(res, 400, "title required");
  };
  let title = raw.trim();
  if title.len() == 0 { return errj(res, 400, "title required"); }
  let Ok(id) = store.add("seq", 1) else { return errj(res, 500, "storage error"); };
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(id));
  m.insert("title", Json::Str(title));
  m.insert("done", Json::Bool(false));
  let text = Json::Obj(m).to_json();
  let Ok(_) = store.set(key(id), text.to_bytes()) else { return errj(res, 500, "storage error"); };
  reply(res, 201, text)
}

fn list(res: Outgoing, store: Kv, query: Str) -> Result<Str, WebErr> {
  let mut want: Option<Bool> = None;
  for p in query.split("&") {
    if p == "done=true" { want = Some(true); }
    if p == "done=false" { want = Some(false); }
  }
  let Ok(keys) = store.keys("todo/") else { return errj(res, 500, "storage error"); };
  let mut items: List<Json> = [];
  for k in keys {
    let Ok(Some(b)) = store.get(k) else { continue; };
    let Ok(j) = b.to_str().parse_json() else { continue; };
    let done = j.get("done").and_then(|d| d.as_bool()).unwrap_or(false);
    let keep = match want {
      Some(w) => w == done,
      None => true,
    };
    if keep { items.push(j); }
  }
  reply(res, 200, Json::Arr(items).to_json())
}

fn patch(res: Outgoing, store: Kv, k: Str, first: Bytes, body: Bytes) -> Result<Str, WebErr> {
  let Some(doc) = parse_obj(body) else { return errj(res, 400, "bad update"); };
  let mut nt: Option<Str> = None;
  let mut nd: Option<Bool> = None;
  match doc.get("title") {
    None => {},
    Some(t) => {
      match t.as_str() {
        Some(s) => {
          let s2 = s.trim();
          if s2.len() == 0 { return errj(res, 400, "bad update"); }
          nt = Some(s2);
        },
        None => return errj(res, 400, "bad update"),
      }
    },
  }
  match doc.get("done") {
    None => {},
    Some(d) => {
      match d.as_bool() {
        Some(v) => nd = Some(v),
        None => return errj(res, 400, "bad update"),
      }
    },
  }
  let mut oldb = first;
  loop {
    let Ok(old) = oldb.to_str().parse_json() else { return errj(res, 500, "storage error"); };
    let mut m = old.as_map().unwrap_or(Map::new());
    if let Some(t) = nt { m.insert("title", Json::Str(t)); }
    if let Some(d) = nd { m.insert("done", Json::Bool(d)); }
    let nb = Json::Obj(m).to_json().to_bytes();
    match store.swap(k, Some(oldb), Some(nb)) {
      Ok(true) => return reply(res, 200, nb.to_str()),
      Ok(false) => {
        match store.get(k) {
          Ok(Some(b)) => oldb = b,
          Ok(None) => return errj(res, 404, "not found"),
          Err(_) => return errj(res, 500, "storage error"),
        }
      },
      Err(_) => return errj(res, 500, "storage error"),
    }
  }
}

fn by_id(res: Outgoing, store: Kv, method: Str, id: Int, body: Bytes) -> Result<Str, WebErr> {
  let k = key(id);
  let Ok(cur) = store.get(k) else { return errj(res, 500, "storage error"); };
  let Some(curb) = cur else { return errj(res, 404, "not found"); };
  if method == "GET" {
    reply(res, 200, curb.to_str())
  } else if method == "DELETE" {
    let Ok(_) = store.delete(k) else { return errj(res, 500, "storage error"); };
    reply(res, 204, "")
  } else if method == "PATCH" {
    patch(res, store, k, curb, body)
  } else {
    errj(res, 404, "not found")
  }
}

fn main(req: Incoming, res: Outgoing, store: Kv) -> Result<Str, WebErr> {
  let method = req.method();
  let target = req.target();
  let mut path = target;
  let mut query = "";
  if let Some(i) = target.find("?") {
    path = target.slice(0, i);
    query = target.slice(i + 1, target.len());
  }
  if path == "/todos" {
    if method == "POST" {
      create(res, store, req.body())
    } else if method == "GET" {
      list(res, store, query)
    } else {
      errj(res, 404, "not found")
    }
  } else if let Some(rest) = path.strip_prefix("/todos/") {
    match parse_id(rest) {
      Some(id) => by_id(res, store, method, id, req.body()),
      None => errj(res, 404, "not found"),
    }
  } else {
    errj(res, 404, "not found")
  }
}

struct Resp { status: Int, body: Json }

fn obj(keys: List<Str>, vals: List<Json>) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  let mut i = 0;
  while i < keys.len() {
    m.insert(keys[i], vals[i]);
    i += 1;
  }
  Json::Obj(m)
}

fn err_resp(status: Int, msg: Str) -> Resp {
  Resp { status: status, body: obj(["error"], [Json::Str(msg)]) }
}

fn not_found() -> Resp { err_resp(404, "not found") }

fn int_of(v: SqlValue) -> Int {
  match v { SqlValue::Int(i) => i, _ => 0 }
}

fn str_of(v: SqlValue) -> Str {
  match v { SqlValue::Text(s) => s, _ => "" }
}

fn parse_id(s: Str) -> Option<Int> {
  let n = s.parse_int()?;
  if n > 0 && n.to_str() == s { Some(n) } else { None }
}

fn parse_tags(j: Json) -> Option<List<Str>> {
  match j.get("tags") {
    None => Some([]),
    Some(t) => {
      let items = t.as_list()?;
      let mut out: List<Str> = [];
      for it in items {
        let s = it.as_str()?;
        let l = s.to_lowercase();
        if !out.contains(l) { out.push(l); }
      }
      Some(out)
    }
  }
}

fn create(body: Str, db: Db) -> Result<Resp, DbErr> {
  let bad = err_resp(400, "invalid note");
  let Ok(j) = body.parse_json() else { return Ok(bad); };
  let Some(_) = j.as_map() else { return Ok(bad); };
  let Some(title) = j.get("title").and_then(|x| x.as_str()) else { return Ok(bad); };
  if title.len() == 0 { return Ok(bad); }
  let Some(text) = j.get("body").and_then(|x| x.as_str()) else { return Ok(bad); };
  let Some(tags) = parse_tags(j) else { return Ok(bad); };
  let tj = Json::Arr(tags.map(|t| Json::Str(t))).to_json();
  let rows = db.query("INSERT INTO notes(title, body, tags) VALUES (?, ?, ?) RETURNING id", [SqlValue::Text(title), SqlValue::Text(text), SqlValue::Text(tj)])?;
  if rows.len() == 0 { return Ok(err_resp(500, "failed")); }
  Ok(Resp { status: 201, body: obj(["id"], [Json::Num(int_of(rows[0][0]))]) })
}

fn list(query: Str, db: Db) -> Result<Resp, DbErr> {
  let mut sql = "SELECT id, title FROM notes WHERE 1=1";
  let mut params: List<SqlValue> = [];
  for part in query.split("&") {
    let kv = part.split("=");
    if kv.len() == 2 {
      if kv[0] == "tag" {
        sql = sql + " AND EXISTS (SELECT 1 FROM json_each(notes.tags) WHERE value = ?)";
        params.push(SqlValue::Text(kv[1].to_lowercase()));
      } else if kv[0] == "q" {
        sql = sql + " AND (instr(title, ?) > 0 OR instr(body, ?) > 0)";
        params.push(SqlValue::Text(kv[1]));
        params.push(SqlValue::Text(kv[1]));
      }
    }
  }
  sql = sql + " ORDER BY id DESC";
  let rows = db.query(sql, params)?;
  let mut out: List<Json> = [];
  for row in rows {
    out.push(obj(["id", "title"], [Json::Num(int_of(row[0])), Json::Str(str_of(row[1]))]));
  }
  Ok(Resp { status: 200, body: Json::Arr(out) })
}

fn get_note(id: Int, db: Db) -> Result<Resp, DbErr> {
  let rows = db.query("SELECT id, title, body, tags FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
  if rows.len() == 0 { return Ok(not_found()); }
  let row = rows[0];
  let tags = str_of(row[3]).parse_json().unwrap_or(Json::Arr([]));
  Ok(Resp { status: 200, body: obj(["id", "title", "body", "tags"], [Json::Num(int_of(row[0])), Json::Str(str_of(row[1])), Json::Str(str_of(row[2])), tags]) })
}

fn delete_note(id: Int, db: Db) -> Result<Resp, DbErr> {
  let n = db.exec("DELETE FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
  if n == 0 { return Ok(not_found()); }
  Ok(Resp { status: 200, body: obj(["deleted"], [Json::Num(id)]) })
}

fn route(method: Str, target: Str, body: Str, db: Db) -> Result<Resp, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)", [])?;
  let mut path: Str = target;
  let mut query: Str = "";
  if let Some(i) = target.find("?") {
    path = target.slice(0, i);
    query = target.slice(i + 1, target.len());
  }
  if path == "/notes" {
    if method == "POST" { return create(body, db); }
    if method == "GET" { return list(query, db); }
    return Ok(not_found());
  }
  if let Some(rest) = path.strip_prefix("/notes/") {
    let Some(id) = parse_id(rest) else { return Ok(not_found()); };
    if method == "GET" { return get_note(id, db); }
    if method == "DELETE" { return delete_note(id, db); }
  }
  Ok(not_found())
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Str {
  let method = req.method();
  let target = req.target();
  let body = req.body();
  let text = if method == "POST" { body.to_str() } else { "" };
  let resp = match route(method, target, text, db) {
    Ok(r) => r,
    Err(_) => err_resp(500, "internal error"),
  };
  match res.send(resp.status, ["content-type"], ["application/json"], resp.body.to_json().to_bytes()) {
    Ok(_) => "ok",
    Err(_) => "send failed",
  }
}

struct Station { name: Str, id: Str }

fn fmt(t: Int) -> Str {
  let sign = if t < 0 { "-" } else { "" };
  let a = if t < 0 { -t } else { t };
  sign + (a / 10).to_str() + "." + (a % 10).to_str()
}

fn summarize(name: Str, body: Bytes) -> Str {
  let doc = match body.to_str().parse_json() {
    Ok(d) => d,
    Err(_) => return name + " unavailable",
  };
  let readings = doc.get("readings").and_then(|j| j.as_list()).unwrap_or([]);
  let mut n = 0;
  let mut sum = 0;
  let mut mn = 0;
  let mut mx = 0;
  for r in readings {
    if let Some(t) = r.get("temp").and_then(|j| j.as_int()) {
      if n == 0 {
        mn = t;
        mx = t;
      } else {
        mn = mn.min(t);
        mx = mx.max(t);
      }
      sum = sum + t;
      n = n + 1;
    }
  }
  if n == 0 {
    return name + " no data";
  }
  name + " min=" + fmt(mn) + " max=" + fmt(mx) + " avg=" + fmt(sum / n) + " n=" + n.to_str()
}

fn main(api: Http) -> Result<Str, HttpErr> {
  let text = api.get("/stations")?.to_str();
  let doc = match text.parse_json() {
    Ok(d) => d,
    Err(_) => return Err(HttpErr::Invalid),
  };
  let items = doc.get("stations").and_then(|j| j.as_list()).unwrap_or([]);
  let mut stations: List<Station> = [];
  for it in items {
    let Some(id) = it.get("id").and_then(|j| j.as_str()) else { continue; };
    let Some(name) = it.get("name").and_then(|j| j.as_str()) else { continue; };
    stations.push(Station { name: name, id: id });
  }
  stations.sort_by_key(|s| s.name);
  let mut lines: List<Str> = [];
  for s in stations {
    let line = match api.get("/stations/" + s.id + "/readings") {
      Ok(b) => summarize(s.name, b),
      Err(_) => s.name + " unavailable",
    };
    lines.push(line);
  }
  Ok(lines.join("\n"))
}

fn fetch(api: Http, page: Int) -> Result<Json, Str> {
  let b = match api.get("/orders?page=" + page.to_str()) {
    Ok(b) => b,
    Err(_) => return Err("get failed"),
  };
  b.to_str().parse_json()
}

fn main(api: Http) -> Result<Str, Str> {
  let mut page = 1;
  let mut count = 0;
  let mut refunded = 0;
  let mut paid: Map<Str, Int> = Map::new();
  let mut has_best = false;
  let mut best_cents = 0;
  let mut best_id = 0;
  loop {
    let doc = fetch(api, page)?;
    let orders = doc.get("orders").and_then(|j| j.as_list()).unwrap_or([]);
    for o in orders {
      count += 1;
      let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
      if status == "refunded" {
        refunded += 1;
      }
      if status == "paid" {
        let id = o.get("id").and_then(|j| j.as_int()).unwrap_or(0);
        let cents = o.get("cents").and_then(|j| j.as_int()).unwrap_or(0);
        let cur = o.get("currency").and_then(|j| j.as_str()).unwrap_or("");
        let old = paid.get(cur).unwrap_or(0);
        paid.insert(cur, old + cents);
        if !has_best || cents > best_cents || (cents == best_cents && id < best_id) {
          has_best = true;
          best_cents = cents;
          best_id = id;
        }
      }
    }
    let next = doc.get("next").and_then(|j| j.as_int());
    if let Some(n) = next {
      page = n;
    } else {
      break;
    }
  }
  let mut pj: Map<Str, Json> = Map::new();
  for k in paid.keys() {
    pj.insert(k, Json::Num(paid.get(k).unwrap_or(0)));
  }
  let mut body: Map<Str, Json> = Map::new();
  body.insert("orders", Json::Num(count));
  body.insert("paid_cents", Json::Obj(pj));
  body.insert("refunded", Json::Num(refunded));
  if has_best {
    body.insert("largest", Json::Num(best_id));
  } else {
    body.insert("largest", Json::Null);
  }
  let payload = Json::Obj(body).to_json().to_bytes();
  let r = match api.send("POST", "/summaries", ["content-type: application/json"], payload, 0) {
    Ok(r) => r,
    Err(_) => return Err("post failed"),
  };
  if r.status != 201 {
    return Err("status " + r.status.to_str());
  }
  let resp = r.body.to_str().parse_json()?;
  match resp.get("id").and_then(|j| j.as_str()) {
    Some(s) => Ok(s),
    None => Err("no id in response"),
  }
}

fn io_err(e: IoErr) -> Str { "io error" }

fn main(input: Dir, cache: Kv) -> Result<Str, Str> {
  let text = input.read("ops.txt").map_err(|e| "io error")?.to_str();
  let lines = text.lines();
  if lines.len() == 0 { return Err("no capacity line"); }
  let head = lines[0].split(" ");
  if head.len() != 2 || head[0] != "capacity" { return Err("bad capacity line"); }
  let Some(cap) = head[1].parse_int() else { return Err("bad capacity"); };
  if cap < 1 { return Err("bad capacity"); }

  let raw = cache.get("state").map_err(|e| "kv error")?;
  let mut doc = Json::Null;
  if let Some(b) = raw { doc = b.to_str().parse_json()?; }
  let mut order: List<Str> = [];
  let ol = doc.get("order").and_then(|j| j.as_list()).unwrap_or([]);
  for j in ol { order.push(j.as_str().unwrap_or("")); }
  let mut vals: Map<Str, Str> = Map::new();
  let vm: Map<Str, Json> = doc.get("vals").and_then(|j| j.as_map()).unwrap_or(Map::new());
  for k in vm.keys() {
    let v = vm.get(k).and_then(|j| j.as_str()).unwrap_or("");
    vals.insert(k, v);
  }
  let mut hits = doc.get("hits").and_then(|j| j.as_int()).unwrap_or(0);
  let mut misses = doc.get("misses").and_then(|j| j.as_int()).unwrap_or(0);
  let mut evictions = doc.get("evictions").and_then(|j| j.as_int()).unwrap_or(0);

  let mut out = "";
  while order.len() > cap {
    let Some(k) = order.pop() else { break; };
    vals.remove(k);
    evictions += 1;
    out = out + "evict " + k + "\n";
  }

  for i in 1..lines.len() {
    let line = lines[i];
    if line == "" { continue; }
    let parts = line.split(" ");
    let op = parts[0];
    let mut ok = false;
    let mut key = "";
    let mut value = "";
    if op == "get" || op == "del" {
      if parts.len() == 2 && parts[1] != "" {
        ok = true;
        key = parts[1];
      }
    } else if op == "put" {
      if let Some(rest) = line.strip_prefix("put ") {
        if let Some(idx) = rest.find(" ") {
          let k = rest.slice(0, idx);
          let v = rest.slice(idx + 1, rest.len());
          if k != "" && v != "" {
            ok = true;
            key = k;
            value = v;
          }
        }
      }
    }
    if !ok {
      out = out + "bad line " + (i + 1).to_str() + "\n";
      continue;
    }
    if op == "get" {
      match vals.get(key) {
        Some(v) => {
          hits += 1;
          let mut n: List<Str> = [key];
          for k in order { if k != key { n.push(k); } }
          order = n;
          out = out + key + "=" + v + "\n";
        }
        None => {
          misses += 1;
          out = out + key + " miss\n";
        }
      }
    } else if op == "del" {
      if vals.get(key).is_some() {
        vals.remove(key);
        let mut n: List<Str> = [];
        for k in order { if k != key { n.push(k); } }
        order = n;
      }
    } else {
      if vals.get(key).is_none() && order.len() >= cap {
        if let Some(k) = order.pop() {
          vals.remove(k);
          evictions += 1;
          out = out + "evict " + k + "\n";
        }
      }
      vals.insert(key, value);
      let mut n: List<Str> = [key];
      for k in order { if k != key { n.push(k); } }
      order = n;
    }
  }

  let mut o: Map<Str, Json> = Map::new();
  o.insert("order", Json::Arr(order.map(|k| Json::Str(k))));
  let mut vo: Map<Str, Json> = Map::new();
  for k in vals.keys() {
    vo.insert(k, Json::Str(vals.get(k).unwrap_or("")));
  }
  o.insert("vals", Json::Obj(vo));
  o.insert("hits", Json::Num(hits));
  o.insert("misses", Json::Num(misses));
  o.insert("evictions", Json::Num(evictions));
  let s = Json::Obj(o).to_json();
  cache.set("state", s.to_bytes()).map_err(|e| "kv error")?;

  if order.len() == 0 {
    out = out + "cache:\n";
  } else {
    out = out + "cache: " + order.join(",") + "\n";
  }
  out = out + "stats hits " + hits.to_str() + " misses " + misses.to_str() + " evictions " + evictions.to_str() + "\n";
  Ok(out)
}

fn strs(j: Json) -> Option<List<Str>> {
  let items = j.as_list()?;
  let mut out: List<Str> = [];
  for x in items {
    let s = x.as_str()?;
    if !out.contains(s) { out.push(s); }
  }
  Some(out)
}

fn reach(adj: List<List<Int>>, i: Int) -> List<Bool> {
  let n = adj.len();
  let mut seen: List<Bool> = [];
  for k in 0..n { seen.push(false); }
  let mut st: List<Int> = [];
  for d in adj[i] { st.push(d); }
  while st.len() > 0 {
    let Some(v) = st.pop() else { break; };
    if !seen[v] {
      seen[v] = true;
      for d in adj[v] { st.push(d); }
    }
  }
  seen
}

fn names(valid: List<Str>, ids: List<Int>) -> Str {
  ids.map(|i| valid[i]).join(", ")
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("packages.json")?.to_str();
  let doc = match text.parse_json() {
    Ok(j) => j,
    Err(_) => return Ok("error: not an object"),
  };
  let Some(m) = doc.as_map() else { return Ok("error: not an object"); };
  let mut valid: List<Str> = [];
  let mut deps: List<List<Str>> = [];
  let mut invalid: List<Str> = [];
  let mut idx: HashMap<Str, Int> = HashMap::new();
  for key in m.keys() {
    let Some(v) = m.get(key) else { continue; };
    match strs(v) {
      Some(l) => {
        idx.insert(key, valid.len());
        valid.push(key);
        deps.push(l);
      }
      None => invalid.push(key),
    }
  }
  let n = valid.len();
  let mut adj: List<List<Int>> = [];
  let mut hasmiss: List<Bool> = [];
  let mut missing: Map<Str, List<Str>> = Map::new();
  for i in 0..n {
    let mut ai: List<Int> = [];
    let mut miss = false;
    for d in deps[i] {
      match idx.get(d) {
        Some(j) => ai.push(j),
        None => {
          miss = true;
          let mut l: List<Str> = missing.get(d).unwrap_or([]);
          l.push(valid[i]);
          missing.insert(d, l);
        }
      }
    }
    adj.push(ai);
    hasmiss.push(miss);
  }
  let mut r: List<List<Bool>> = [];
  for i in 0..n { r.push(reach(adj, i)); }

  let mut bad: List<Bool> = [];
  let mut assigned: List<Bool> = [];
  for i in 0..n {
    bad.push(hasmiss[i] || r[i][i]);
    assigned.push(false);
  }
  let mut changed = true;
  while changed {
    changed = false;
    for i in 0..n {
      if bad[i] { continue; }
      for d in adj[i] {
        if bad[d] {
          bad[i] = true;
          changed = true;
          break;
        }
      }
    }
  }
  let mut stage: List<Int> = [];
  for i in 0..n { stage.push(0); }
  changed = true;
  while changed {
    changed = false;
    for i in 0..n {
      if bad[i] { continue; }
      let mut mx = 0;
      for d in adj[i] { mx = mx.max(stage[d]); }
      if stage[i] != mx + 1 {
        stage[i] = mx + 1;
        changed = true;
      }
    }
  }
  let mut maxs = 0;
  let mut built = 0;
  for i in 0..n {
    if !bad[i] {
      built += 1;
      maxs = maxs.max(stage[i]);
    }
  }
  let mut lines: List<Str> = [];
  for s in 1..(maxs + 1) {
    let mut ids: List<Int> = [];
    for i in 0..n {
      if !bad[i] && stage[i] == s { ids.push(i); }
    }
    lines.push("stage " + s.to_str() + ": " + names(valid, ids));
  }
  for i in 0..n {
    if assigned[i] || !r[i][i] { continue; }
    let mut group: List<Int> = [];
    for j in 0..n {
      if r[i][j] && r[j][i] {
        group.push(j);
        assigned[j] = true;
      }
    }
    lines.push("cycle: " + names(valid, group));
  }
  for k in missing.keys() {
    let l: List<Str> = missing.get(k).unwrap_or([]);
    lines.push("missing: " + k + " (needed by " + l.join(", ") + ")");
  }
  if invalid.len() > 0 {
    lines.push("invalid: " + invalid.join(", "));
  }
  let mut blocked: List<Int> = [];
  for i in 0..n {
    if bad[i] && !r[i][i] { blocked.push(i); }
  }
  if blocked.len() > 0 {
    lines.push("blocked: " + names(valid, blocked));
  }
  lines.push("built " + built.to_str() + " of " + n.to_str());
  Ok(lines.join("\n"))
}

struct Bk { room: Str, day: Str, s: Int, e: Int, who: Str }
struct Iv { s: Int, e: Int }
struct Cf { start: Int, text: Str }

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn fmt(n: Int) -> Str {
  pad2(n / 60) + ":" + pad2(n % 60)
}

fn parse_time(t: Str) -> Option<Int> {
  if t.len() != 5 { return None; }
  let b = t.to_bytes();
  if b[2] != 58 { return None; }
  for i in [0, 1, 3, 4] {
    if b[i] < 48 || b[i] > 57 { return None; }
  }
  let h = (b[0] - 48) * 10 + (b[1] - 48);
  let m = (b[3] - 48) * 10 + (b[4] - 48);
  if m > 59 { return None; }
  if h > 24 { return None; }
  if h == 24 && m != 0 { return None; }
  Some(h * 60 + m)
}

fn parse_line(line: Str) -> Option<Bk> {
  let parts = line.split(",");
  if parts.len() != 5 { return None; }
  let s = parse_time(parts[2])?;
  let e = parse_time(parts[3])?;
  if e <= s { return None; }
  Some(Bk { room: parts[0], day: parts[1], s: s, e: e, who: parts[4] })
}

fn render(room: Str, day: Str, bks: List<Bk>) -> Str {
  let mut sorted = bks;
  sorted.sort_by_key(|b| b.s);
  let mut merged: List<Iv> = [];
  for b in sorted {
    if merged.len() > 0 && b.s <= merged[merged.len() - 1].e {
      let k = merged.len() - 1;
      if b.e > merged[k].e { merged[k].e = b.e; }
    } else {
      merged.push(Iv { s: b.s, e: b.e });
    }
  }
  let mut busy: List<Str> = [];
  let mut free: List<Str> = [];
  let mut cursor = 540;
  for iv in merged {
    busy.push(fmt(iv.s) + "-" + fmt(iv.e));
    if iv.s > cursor {
      let ge = iv.s.min(1080);
      if ge - cursor >= 30 { free.push(fmt(cursor) + "-" + fmt(ge)); }
    }
    cursor = cursor.max(iv.e);
  }
  if 1080 - cursor >= 30 { free.push(fmt(cursor) + "-" + fmt(1080)); }
  let mut cfs: List<Cf> = [];
  let n = bks.len();
  for i in 0..n {
    for j in (i + 1)..n {
      let a = bks[i];
      let b = bks[j];
      let lo = a.s.max(b.s);
      let hi = a.e.min(b.e);
      if hi > lo {
        let mut x = a.who;
        let mut y = b.who;
        if y < x { x = b.who; y = a.who; }
        cfs.push(Cf { start: lo, text: x + "/" + y + " " + fmt(lo) + "-" + fmt(hi) });
      }
    }
  }
  cfs.sort_by(|a, b| a.start < b.start || (a.start == b.start && a.text < b.text));
  let mut out = room + " " + day + "\n";
  out = out + "  busy " + busy.join(", ") + "\n";
  if free.len() == 0 {
    out = out + "  free none\n";
  } else {
    out = out + "  free " + free.join(", ") + "\n";
  }
  for c in cfs {
    out = out + "  conflict " + c.text + "\n";
  }
  out
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("bookings.csv")?.to_str();
  let lines = text.lines();
  let mut groups: Map<Str, List<Bk>> = Map::new();
  let mut seen: Map<Str, Bool> = Map::new();
  let mut skipped: List<Str> = [];
  for idx in 0..lines.len() {
    if idx == 0 { continue; }
    let line = lines[idx];
    if line.trim() == "" { continue; }
    match parse_line(line) {
      None => skipped.push((idx + 1).to_str()),
      Some(b) => {
        if seen.get(line).is_none() {
          seen.insert(line, true);
          let key = b.room + "\n" + b.day;
          let mut cur: List<Bk> = groups.get(key).unwrap_or([]);
          cur.push(b);
          groups.insert(key, cur);
        }
      }
    }
  }
  let mut out = "";
  for key in groups.keys() {
    let parts = key.split("\n");
    let bks = groups.get(key).unwrap_or([]);
    out = out + render(parts[0], parts[1], bks);
  }
  if skipped.len() == 0 {
    out = out + "skipped: none\n";
  } else {
    out = out + "skipped: " + skipped.join(", ") + "\n";
  }
  Ok(out)
}

struct Problem { path: Str, msg: Str }

fn bad(path: Str, msg: Str) -> Problem {
  Problem { path: path, msg: msg }
}

fn validate(schema: Json, v: Json, path: Str) -> List<Problem> {
  let t = schema.get("type").and_then(|j| j.as_str()).unwrap_or("");
  let mut errs: List<Problem> = [];
  match t {
    "object" => {
      match v {
        Json::Obj(m) => {
          let props: Map<Str, Json> = schema.get("properties").and_then(|j| j.as_map()).unwrap_or(Map::new());
          let required: List<Json> = schema.get("required").and_then(|j| j.as_list()).unwrap_or([]);
          let additional = schema.get("additional").and_then(|j| j.as_bool()).unwrap_or(true);
          for r in required {
            if let Some(name) = r.as_str() {
              if m.get(name).is_none() {
                errs.push(bad(path + "." + name, "missing required field"));
              }
            }
          }
          for key in m.keys() {
            let p = path + "." + key;
            match props.get(key) {
              Some(s) => {
                let sub = validate(s, m.get(key).unwrap_or(Json::Null), p);
                for e in sub { errs.push(e); }
              }
              None => {
                if !additional { errs.push(bad(p, "unexpected field")); }
              }
            }
          }
        }
        _ => { errs.push(bad(path, "expected object")); }
      }
    }
    "array" => {
      match v {
        Json::Arr(xs) => {
          if let Some(n) = schema.get("min_items").and_then(|j| j.as_int()) {
            if xs.len() < n {
              errs.push(bad(path, "fewer than " + n.to_str() + " items"));
            }
          }
          if let Some(s) = schema.get("items") {
            for i in 0..xs.len() {
              let sub = validate(s, xs[i], path + "[" + i.to_str() + "]");
              for e in sub { errs.push(e); }
            }
          }
        }
        _ => { errs.push(bad(path, "expected array")); }
      }
    }
    "string" => {
      match v {
        Json::Str(s) => {
          let n = s.chars().len();
          let mn = schema.get("min_length").and_then(|j| j.as_int());
          let mx = schema.get("max_length").and_then(|j| j.as_int());
          let en = schema.get("enum").and_then(|j| j.as_list());
          let mut done = false;
          if let Some(a) = mn {
            if n < a { errs.push(bad(path, "shorter than " + a.to_str())); done = true; }
          }
          if !done {
            if let Some(b) = mx {
              if n > b { errs.push(bad(path, "longer than " + b.to_str())); done = true; }
            }
          }
          if !done {
            if let Some(list) = en {
              if !list.any(|j| j.as_str() == Some(s)) {
                errs.push(bad(path, "not in enum"));
              }
            }
          }
        }
        _ => { errs.push(bad(path, "expected string")); }
      }
    }
    "integer" | "number" => {
      let mn = schema.get("minimum").and_then(|j| j.as_int());
      let mx = schema.get("maximum").and_then(|j| j.as_int());
      let mut ok = false;
      let mut lo = false;
      let mut hi = false;
      match v {
        Json::Num(n) => {
          ok = true;
          if let Some(a) = mn { if n < a { lo = true; } }
          if let Some(b) = mx { if n > b { hi = true; } }
        }
        Json::Float(f) => {
          ok = t == "number";
          if let Some(a) = mn { if f < a.to_float() { lo = true; } }
          if let Some(b) = mx { if f > b.to_float() { hi = true; } }
        }
        _ => {}
      }
      if !ok {
        errs.push(bad(path, "expected " + t));
      } else if lo {
        errs.push(bad(path, "less than " + mn.unwrap_or(0).to_str()));
      } else if hi {
        errs.push(bad(path, "greater than " + mx.unwrap_or(0).to_str()));
      }
    }
    "boolean" => {
      let ok = match v { Json::Bool(_) => true, _ => false };
      if !ok { errs.push(bad(path, "expected boolean")); }
    }
    "null" => {
      let ok = match v { Json::Null => true, _ => false };
      if !ok { errs.push(bad(path, "expected null")); }
    }
    _ => {}
  }
  errs
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let schema_text = input.read("schema.json")?.to_str();
  let text = input.read("records.jsonl")?.to_str();
  let schema = match schema_text.parse_json() {
    Ok(j) => j,
    Err(_) => { return Ok("invalid schema"); }
  };
  let mut out: List<Str> = [];
  let mut valid = 0;
  let mut total = 0;
  let lines = text.lines();
  for i in 0..lines.len() {
    let line = lines[i];
    if line.trim().len() == 0 { continue; }
    total += 1;
    let prefix = "line " + (i + 1).to_str() + ": ";
    match line.parse_json() {
      Err(_) => { out.push(prefix + "invalid JSON"); }
      Ok(v) => {
        let mut errs = validate(schema, v, "$");
        if errs.len() == 0 {
          valid += 1;
          out.push(prefix + "ok");
        } else {
          errs.sort_by(|a, b| a.path < b.path || (a.path == b.path && a.msg < b.msg));
          for e in errs {
            out.push(prefix + e.path + ": " + e.msg);
          }
        }
      }
    }
  }
  out.push("valid " + valid.to_str() + " of " + total.to_str());
  Ok(out.join("\n"))
}

