}

fn push(api: Http, id: Str, body: Bytes) -> Str {
  let mut attempt = 0;
  let mut result = "failed";
  let mut done = false;
  while attempt < 3 && !done {
    attempt += 1;
    match api.send("PUT", "/records/" + id, ["content-type: application/json"], body, 0) {
      Ok(r) => {
        if r.status >= 200 && r.status < 300 {
          result = "synced";
          done = true;
        } else if r.status >= 400 && r.status < 500 {
          result = "rejected " + r.status.to_str();
          done = true;
        }
      }
      Err(_) => {}
    }
  }
  result.to_str()
}

