  let text = input.read("records.jsonl")?.to_str();
  let mut recs: Map<Str, Json> = Map::new();
  let mut vers: Map<Str, Int> = Map::new();
  let mut out = "";
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    if line.trim().len() == 0 { continue; }
