    recs.insert(id, j);
    vers.insert(id, v);
  }
  let mut synced = 0;
  let mut unchanged = 0;
  let mut rejected = 0;
  let mut failed = 0;
  for id in recs.keys() {
    let v = vers.get(id).unwrap_or(0);
    let skip = match last_version(state, id) {
      Some(l) => v <= l,
      None => false,
    };
