const MAXI: Int = 9223372036854775807;

enum Out { Ok, Dup, Fail(Str) }

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn fmt_time(ms: Int) -> Str {
  let secs = ms / 1000;
  let days = secs / 86400;
  let rem = secs % 86400;
  let z = days + 719468;
  let era = z / 146097;
  let doe = z - era * 146097;
  let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
  let y0 = yoe + era * 400;
  let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
  let mp = (5 * doy + 2) / 153;
  let d = doy - (153 * mp + 2) / 5 + 1;
  let m = if mp < 10 { mp + 3 } else { mp - 9 };
  let y = if m <= 2 { y0 + 1 } else { y0 };
  y.to_str() + "-" + pad2(m) + "-" + pad2(d) + "T" + pad2(rem / 3600) + ":" + pad2((rem % 3600) / 60) + ":" + pad2(rem % 60) + "Z"
}

fn as_int(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(i) => i,
    _ => 0,
  }
}

fn as_text(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn ever_exists(db: Db, name: Str) -> Result<Bool, DbErr> {
  let rows = db.query("SELECT 1 FROM accounts WHERE name = ?", [SqlValue::Text(name)])?;
  Ok(rows.len() > 0)
}

fn balance(db: Db, name: Str) -> Result<Option<Int>, DbErr> {
  let rows = db.query("SELECT balance FROM accounts WHERE name = ? AND closed = 0", [SqlValue::Text(name)])?;
  if rows.len() == 0 { return Ok(None); }
  Ok(Some(as_int(rows[0][0])))
}

fn process(db: Db, now: Int, line: Str) -> Result<Out, DbErr> {
  let w = line.split(" ");
  let op = w[0];
  if op == "open" {
    if w.len() != 3 { return Ok(Out::Fail("malformed")); }
    let Some(c) = w[2].parse_int() else { return Ok(Out::Fail("malformed")); };
    let name = w[1];
    if c < 0 { return Ok(Out::Fail("bad amount")); }
    if ever_exists(db, name)? { return Ok(Out::Fail("account exists")); }
    db.exec("INSERT INTO accounts(name, balance, closed, last_ms) VALUES(?, ?, 0, ?)", [SqlValue::Text(name), SqlValue::Int(c), SqlValue::Int(now)])?;
    return Ok(Out::Ok);
  }
  if op == "close" {
    if w.len() != 2 { return Ok(Out::Fail("malformed")); }
    let name = w[1];
    let Some(b) = balance(db, name)? else { return Ok(Out::Fail("no account " + name)); };
    if b != 0 { return Ok(Out::Fail("balance not zero")); }
    db.exec("UPDATE accounts SET closed = 1, last_ms = ? WHERE name = ?", [SqlValue::Int(now), SqlValue::Text(name)])?;
    return Ok(Out::Ok);
  }
  if op == "transfer" {
    if w.len() != 5 { return Ok(Out::Fail("malformed")); }
    let Some(c) = w[4].parse_int() else { return Ok(Out::Fail("malformed")); };
    let id = w[1];
    let from = w[2];
    let to = w[3];
    let prev = db.query("SELECT src, dst, cents FROM transfers WHERE id = ?", [SqlValue::Text(id)])?;
    if prev.len() > 0 {
      let r = prev[0];
      if as_text(r[0]) == from && as_text(r[1]) == to && as_int(r[2]) == c {
        return Ok(Out::Dup);
      }
      return Ok(Out::Fail("id reused"));
    }
    if c <= 0 { return Ok(Out::Fail("bad amount")); }
    if from == to { return Ok(Out::Fail("same account")); }
    let Some(bf) = balance(db, from)? else { return Ok(Out::Fail("no account " + from)); };
    let Some(bt) = balance(db, to)? else { return Ok(Out::Fail("no account " + to)); };
    if bf < c { return Ok(Out::Fail("insufficient funds")); }
    if bt > MAXI - c { return Ok(Out::Fail("overflow")); }
    let stmts = [
      "UPDATE accounts SET balance = balance - ?, last_ms = ? WHERE name = ?",
      "UPDATE accounts SET balance = balance + ?, last_ms = ? WHERE name = ?",
      "INSERT INTO transfers(id, src, dst, cents) VALUES(?, ?, ?, ?)"
    ];
    let params = [
      [SqlValue::Int(c), SqlValue::Int(now), SqlValue::Text(from)],
      [SqlValue::Int(c), SqlValue::Int(now), SqlValue::Text(to)],
      [SqlValue::Text(id), SqlValue::Text(from), SqlValue::Text(to), SqlValue::Int(c)]
    ];
    db.transaction(stmts, params)?;
    return Ok(Out::Ok);
  }
  Ok(Out::Fail("malformed"))
}

fn setup(db: Db) -> Result<(), DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS accounts(name TEXT PRIMARY KEY, balance INTEGER NOT NULL, closed INTEGER NOT NULL, last_ms INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS transfers(id TEXT PRIMARY KEY, src TEXT NOT NULL, dst TEXT NOT NULL, cents INTEGER NOT NULL)", [])?;
  Ok(())
}

fn report(db: Db) -> Result<Str, DbErr> {
  let rows = db.query("SELECT name, balance, last_ms FROM accounts WHERE closed = 0 ORDER BY name", [])?;
  let mut out = "";
  for r in rows {
    out = out + as_text(r[0]) + " " + as_int(r[1]).to_str() + " last " + fmt_time(as_int(r[2])) + "\n";
  }
  Ok(out)
}

fn main(input: Dir, db: Db, log: Log, clock: Clock) -> Result<Str, Str> {
  let now = clock.now_ms();
  let ts = fmt_time(now);
  setup(db).map_err(|e| "db error")?;
  let text = input.read("ops.txt").map_err(|e| "read error")?.to_str();
  let lines = text.lines();
  let mut okc = 0;
  let mut failed = 0;
  let mut dup = 0;
  for i in 0..lines.len() {
    let line = lines[i];
    if line.trim().len() == 0 { continue; }
    let out = process(db, now, line).map_err(|e| "db error")?;
    match out {
      Out::Ok => okc += 1,
      Out::Dup => dup += 1,
      Out::Fail(m) => {
        failed += 1;
        log.write(ts + " line " + (i + 1).to_str() + ": " + m).map_err(|e| "log error")?;
      },
    }
  }
  let rep = report(db).map_err(|e| "db error")?;
  Ok("ok " + okc.to_str() + " failed " + failed.to_str() + " duplicate " + dup.to_str() + "\n" + rep)
}

struct Resp { status: Int, body: Str }
struct Creds { name: Str, pw: Str }

fn jerr(status: Int, msg: Str) -> Resp {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Resp { status: status, body: Json::Obj(m).to_json() }
}

fn parse_creds(req: Incoming) -> Option<Creds> {
  let doc = req.body().to_str().parse_json().ok()?;
  let name = doc.get("name").and_then(|j| j.as_str())?;
  let pw = doc.get("password").and_then(|j| j.as_str())?;
  Some(Creds { name: name, pw: pw })
}

fn valid_name(n: Str) -> Bool {
  let l = n.len();
  if l < 3 || l > 20 { return false; }
  for b in n.to_bytes() {
    let ok = (b >= 97 && b <= 122) || (b >= 48 && b <= 57) || b == 95;
    if !ok { return false; }
  }
  true
}

fn hash(c: Creds) -> Bytes { (c.name + ":" + c.pw).sha256() }

fn get_int(store: Kv, key: Str) -> Result<Int, KvErr> {
  match store.get(key)? {
    Some(b) => Ok(b.to_str().parse_int().unwrap_or(0)),
    None => Ok(0),
  }
}

fn create_user(req: Incoming, store: Kv) -> Result<Resp, KvErr> {
  let Some(c) = parse_creds(req) else { return Ok(jerr(400, "invalid")); };
  if !valid_name(c.name) || c.pw.len() < 8 { return Ok(jerr(400, "invalid")); }
  let ok = store.swap("user:" + c.name, None, Some(hash(c)))?;
  if !ok { return Ok(jerr(409, "name taken")); }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("name", Json::Str(c.name));
  Ok(Resp { status: 201, body: Json::Obj(m).to_json() })
}

fn login(req: Incoming, store: Kv, clock: Clock, rng: Rng) -> Result<Resp, KvErr> {
  let Some(c) = parse_creds(req) else { return Ok(jerr(401, "bad credentials")); };
  if c.name.len() < 3 || c.name.len() > 20 { return Ok(jerr(401, "bad credentials")); }
  let now = clock.now_ms();
  let until = get_int(store, "lock:" + c.name)?;
  if now < until { return Ok(jerr(429, "locked")); }
  let stored = store.get("user:" + c.name)?;
  let Some(h) = stored else { return Ok(jerr(401, "bad credentials")); };
  if !h.ct_eq(hash(c)) {
    let f = store.add("fails:" + c.name, 1)?;
    if f >= 3 {
      store.set("lock:" + c.name, (now + 900000).to_str().to_bytes())?;
      store.set("fails:" + c.name, "0".to_bytes())?;
    }
    return Ok(jerr(401, "bad credentials"));
  }
  store.set("fails:" + c.name, "0".to_bytes())?;
  store.add("logins:" + c.name, 1)?;
  let token = rng.bytes(16).to_hex();
  store.set("sess:" + token, (c.name + "," + (now + 1800000).to_str()).to_bytes())?;
  let mut m: Map<Str, Json> = Map::new();
  m.insert("token", Json::Str(token));
  m.insert("expires_in", Json::Num(1800));
  Ok(Resp { status: 200, body: Json::Obj(m).to_json() })
}

// returns (token, name) as "token,name" style via Creds
fn auth(req: Incoming, store: Kv, now: Int) -> Result<Option<Creds>, KvErr> {
  let names = req.header_names();
  let values = req.header_values();
  let mut token = "";
  let mut found = false;
  for i in 0..names.len() {
    if names[i] == "authorization" && !found {
      if let Some(t) = values[i].strip_prefix("Bearer ") {
        token = t;
        found = true;
      }
    }
  }
  if !found || token.len() != 32 { return Ok(None); }
  let Some(b) = store.get("sess:" + token)? else { return Ok(None); };
  let parts = b.to_str().split(",");
  if parts.len() != 2 { return Ok(None); }
  let exp = parts[1].parse_int().unwrap_or(0);
  if now >= exp { return Ok(None); }
  Ok(Some(Creds { name: parts[0], pw: token }))
}

fn me(req: Incoming, store: Kv, clock: Clock) -> Result<Resp, KvErr> {
  let now = clock.now_ms();
  let Some(s) = auth(req, store, now)? else { return Ok(jerr(401, "unauthorized")); };
  store.set("sess:" + s.pw, (s.name + "," + (now + 1800000).to_str()).to_bytes())?;
  let n = get_int(store, "logins:" + s.name)?;
  let mut m: Map<Str, Json> = Map::new();
  m.insert("name", Json::Str(s.name));
  m.insert("logins", Json::Num(n));
  Ok(Resp { status: 200, body: Json::Obj(m).to_json() })
}

fn logout(req: Incoming, store: Kv, clock: Clock) -> Result<Resp, KvErr> {
  let now = clock.now_ms();
  let Some(s) = auth(req, store, now)? else { return Ok(jerr(401, "unauthorized")); };
  store.delete("sess:" + s.pw)?;
  Ok(Resp { status: 204, body: "" })
}

fn handle(req: Incoming, store: Kv, clock: Clock, rng: Rng) -> Result<Resp, KvErr> {
  let m = req.method();
  let path = req.target().split("?")[0];
  if m == "POST" && path == "/users" { return create_user(req, store); }
  if m == "POST" && path == "/login" { return login(req, store, clock, rng); }
  if m == "GET" && path == "/me" { return me(req, store, clock); }
  if m == "POST" && path == "/logout" { return logout(req, store, clock); }
  Ok(jerr(404, "not found"))
}

fn main(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Result<Str, WebErr> {
  let r = match handle(req, store, clock, rng) {
    Ok(x) => x,
    Err(_) => jerr(500, "internal"),
  };
  if r.status == 204 {
    res.send(204, [], [], "".to_bytes())?;
  } else {
    res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes())?;
  }
  Ok("")
}

struct Resp { status: Int, body: Str }

fn fail(status: Int, msg: Str) -> Resp {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Resp { status: status, body: Json::Obj(m).to_json() }
}

fn tval(v: SqlValue) -> Str {
  match v { SqlValue::Text(s) => s, _ => "" }
}

fn ival(v: SqlValue) -> Int {
  match v { SqlValue::Int(i) => i, _ => 0 }
}

fn pay_json(row: List<SqlValue>) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Str("pay_" + ival(row[0]).to_str()));
  m.insert("account", Json::Str(tval(row[1])));
  m.insert("cents", Json::Num(ival(row[2])));
  m.insert("currency", Json::Str(tval(row[3])));
  m.insert("status", Json::Str(tval(row[4])));
  m.insert("refunded", Json::Num(ival(row[5])));
  Json::Obj(m)
}

fn ensure(db: Db) -> Result<(), DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS payments (n INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL)", [])?;
  db.exec("CREATE INDEX IF NOT EXISTS payments_account ON payments(account)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS idem (k TEXT PRIMARY KEY, method TEXT NOT NULL, path TEXT NOT NULL, body TEXT NOT NULL, status INTEGER NOT NULL, resp TEXT NOT NULL)", [])?;
  Ok(())
}

fn get_pay(db: Db, n: Int) -> Result<Option<Json>, DbErr> {
  let rows = db.query("SELECT n, account, cents, currency, status, refunded FROM payments WHERE n = ?", [SqlValue::Int(n)])?;
  if rows.len() == 0 { return Ok(None); }
  Ok(Some(pay_json(rows[0])))
}

fn ok_pay(db: Db, n: Int) -> Result<Resp, DbErr> {
  match get_pay(db, n)? {
    Some(j) => Ok(Resp { status: 200, body: j.to_json() }),
    None => Ok(fail(404, "not found")),
  }
}

fn parse_id(s: Str) -> Int {
  let Some(r) = s.strip_prefix("pay_") else { return 0; };
  let Some(n) = r.parse_int() else { return 0; };
  if n > 0 && r == n.to_str() { n } else { 0 }
}

fn create(db: Db, body: Str) -> Result<Resp, DbErr> {
  let bad = fail(422, "invalid payment");
  let Ok(j) = body.parse_json() else { return Ok(bad); };
  let Some(m) = j.as_map() else { return Ok(bad); };
  let Some(acc) = j.get("account").and_then(|x| x.as_str()) else { return Ok(bad); };
  let Some(cents) = j.get("cents").and_then(|x| x.as_int()) else { return Ok(bad); };
  let Some(cur) = j.get("currency").and_then(|x| x.as_str()) else { return Ok(bad); };
  if m.len() != 3 || acc.len() == 0 || cents <= 0 || (cur != "EUR" && cur != "USD") {
    return Ok(bad);
  }
  let rows = db.query("INSERT INTO payments(account, cents, currency, status, refunded) VALUES (?, ?, ?, 'pending', 0) RETURNING n", [SqlValue::Text(acc), SqlValue::Int(cents), SqlValue::Text(cur)])?;
  let n = ival(rows[0][0]);
  match get_pay(db, n)? {
    Some(p) => Ok(Resp { status: 201, body: p.to_json() }),
    None => Ok(fail(404, "not found")),
  }
}

fn status_of(p: Json) -> Str {
  p.get("status").and_then(|x| x.as_str()).unwrap_or("")
}

fn act(db: Db, n: Int, action: Str) -> Result<Resp, DbErr> {
  let Some(p) = get_pay(db, n)? else { return Ok(fail(404, "not found")); };
  let st = status_of(p);
  if action == "capture" {
    if st == "captured" { return ok_pay(db, n); }
    if st == "pending" {
      db.exec("UPDATE payments SET status = 'captured' WHERE n = ? AND status = 'pending'", [SqlValue::Int(n)])?;
      return ok_pay(db, n);
    }
    return Ok(fail(409, "invalid transition"));
  }
  if st == "pending" {
    db.exec("UPDATE payments SET status = 'canceled' WHERE n = ? AND status = 'pending'", [SqlValue::Int(n)])?;
    return ok_pay(db, n);
  }
  Ok(fail(409, "invalid transition"))
}

fn refund(db: Db, n: Int, body: Str) -> Result<Resp, DbErr> {
  let Some(p) = get_pay(db, n)? else { return Ok(fail(404, "not found")); };
  let bad = fail(422, "invalid refund");
  let Ok(j) = body.parse_json() else { return Ok(bad); };
  let Some(amt) = j.get("cents").and_then(|x| x.as_int()) else { return Ok(bad); };
  if amt <= 0 { return Ok(bad); }
  if status_of(p) != "captured" { return Ok(fail(409, "invalid transition")); }
  let cents = p.get("cents").and_then(|x| x.as_int()).unwrap_or(0);
  let refunded = p.get("refunded").and_then(|x| x.as_int()).unwrap_or(0);
  if amt > cents - refunded { return Ok(fail(409, "exceeds captured")); }
  db.exec("UPDATE payments SET refunded = refunded + ?, status = CASE WHEN refunded + ? = cents THEN 'refunded' ELSE status END WHERE n = ? AND status = 'captured' AND refunded + ? <= cents", [SqlValue::Int(amt), SqlValue::Int(amt), SqlValue::Int(n), SqlValue::Int(amt)])?;
  ok_pay(db, n)
}

fn claim(db: Db, k: Str, method: Str, path: Str, canon: Str) -> Result<Option<Resp>, DbErr> {
  let rows = db.query("SELECT method, path, body, status, resp FROM idem WHERE k = ?", [SqlValue::Text(k)])?;
  if rows.len() > 0 {
    let r = rows[0];
    let st = ival(r[3]);
    if st == 0 || tval(r[0]) != method || tval(r[1]) != path || tval(r[2]) != canon {
      return Ok(Some(fail(409, "key reused")));
    }
    return Ok(Some(Resp { status: st, body: tval(r[4]) }));
  }
  match db.exec("INSERT INTO idem(k, method, path, body, status, resp) VALUES (?, ?, ?, ?, 0, '')", [SqlValue::Text(k), SqlValue::Text(method), SqlValue::Text(path), SqlValue::Text(canon)]) {
    Ok(_) => {},
    Err(DbErr::Constraint(_)) => return Ok(Some(fail(409, "key reused"))),
    Err(e) => return Err(e),
  }
  Ok(None)
}

fn release(db: Db, k: Str) -> Result<(), DbErr> {
  db.exec("DELETE FROM idem WHERE k = ?", [SqlValue::Text(k)])?;
  Ok(())
}

fn handle(req: Incoming, db: Db) -> Result<Resp, DbErr> {
  ensure(db)?;
  let method = req.method();
  let target = req.target();
  let path = match target.find("?") { Some(i) => target.slice(0, i), None => target };
  let query = match target.find("?") { Some(i) => target.slice(i + 1, target.len()), None => "" };
  let body = req.body().to_str();
  let names = req.header_names();
  let values = req.header_values();
  let mut key: Option<Str> = None;
  let mut i = 0;
  while i < names.len() {
    if names[i] == "idempotency-key" && key.is_none() { key = Some(values[i]); }
    i += 1;
  }
  let segs = path.split("/");
  let in_pay = segs.len() >= 3 && segs[0] == "" && segs[1] == "payments";
  let is_create = method == "POST" && path == "/payments";
  let is_refund = method == "POST" && segs.len() == 4 && in_pay && segs[3] == "refund";
  if is_create || is_refund {
    let Some(k) = key else { return Ok(fail(400, "missing idempotency key")); };
    let canon = match body.parse_json() { Ok(j) => j.to_json(), Err(_) => body };
    match claim(db, k, method, path, canon)? {
      Some(r) => return Ok(r),
      None => {},
    }
    let r = if is_create { create(db, body) } else { refund(db, parse_id(segs[2]), body) };
    match r {
      Ok(resp) => {
        if resp.status >= 200 && resp.status < 300 {
          db.exec("UPDATE idem SET status = ?, resp = ? WHERE k = ?", [SqlValue::Int(resp.status), SqlValue::Text(resp.body), SqlValue::Text(k)])?;
        } else {
          release(db, k)?;
        }
        return Ok(resp);
      },
      Err(e) => {
        release(db, k)?;
        return Err(e);
      },
    }
  }
  if method == "GET" && path == "/payments" {
    let mut acc = "";
    for part in query.split("&") {
      if let Some(a) = part.strip_prefix("account=") { acc = a; }
    }
    let rows = db.query("SELECT n, account, cents, currency, status, refunded FROM payments WHERE account = ? ORDER BY n", [SqlValue::Text(acc)])?;
    let mut out: List<Json> = [];
    for r in rows { out.push(pay_json(r)); }
    return Ok(Resp { status: 200, body: Json::Arr(out).to_json() });
  }
  if in_pay && segs.len() == 3 && method == "GET" {
    let n = parse_id(segs[2]);
    if n == 0 { return Ok(fail(404, "not found")); }
    return ok_pay(db, n);
  }
  if in_pay && segs.len() == 4 && method == "POST" && (segs[3] == "capture" || segs[3] == "cancel") {
    let n = parse_id(segs[2]);
    if n == 0 { return Ok(fail(404, "not found")); }
    return act(db, n, segs[3]);
  }
  Ok(fail(404, "not found"))
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, WebErr> {
  let r = match handle(req, db) {
    Ok(r) => r,
    Err(_) => fail(500, "internal error"),
  };
  res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes())?;
  Ok("")
}

struct Ev { user: Str, page: Str, t: Int }
struct PC { page: Str, n: Int }

fn pad2(n: Int) -> Str {
  if n < 10 { "0".to_str() + n.to_str() } else { n.to_str() }
}

fn hms(d: Int) -> Str {
  pad2(d / 3600) + ":" + pad2((d % 3600) / 60) + ":" + pad2(d % 60)
}

fn line_for(user: Str, sessions: Int, events: Int, longest: Int, pages: Int) -> Str {
  user + " sessions " + sessions.to_str() + " events " + events.to_str() + " longest " + hms(longest) + " pages " + pages.to_str()
}

fn parse_time(t: Str) -> Option<Int> {
  if t.len() != 20 { return None; }
  let b = t.to_bytes();
  for i in 0..20 {
    let c = b[i];
    if i == 4 || i == 7 {
      if c != 45 { return None; }
    } else if i == 10 {
      if c != 84 { return None; }
    } else if i == 13 || i == 16 {
      if c != 58 { return None; }
    } else if i == 19 {
      if c != 90 { return None; }
    } else {
      if c < 48 || c > 57 { return None; }
    }
  }
  let y = t.slice(0, 4).parse_int()?;
  let mo = t.slice(5, 7).parse_int()?;
  let d = t.slice(8, 10).parse_int()?;
  let hh = t.slice(11, 13).parse_int()?;
  let mi = t.slice(14, 16).parse_int()?;
  let ss = t.slice(17, 19).parse_int()?;
  if mo < 1 || mo > 12 { return None; }
  if hh > 23 || mi > 59 || ss > 59 { return None; }
  let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
  let dim = if mo == 2 {
    if leap { 29 } else { 28 }
  } else if mo == 4 || mo == 6 || mo == 9 || mo == 11 {
    30
  } else {
    31
  };
  if d < 1 || d > dim { return None; }
  let yy = (if mo <= 2 { y - 1 } else { y }) + 400;
  let era = yy / 400;
  let yoe = yy - era * 400;
  let mp = if mo > 2 { mo - 3 } else { mo + 9 };
  let doy = (153 * mp + 2) / 5 + d - 1;
  let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  let days = era * 146097 + doe;
  Some(days * 86400 + hh * 3600 + mi * 60 + ss)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("events.log")?.to_str();
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut evs: List<Ev> = [];
  let mut malformed = 0;
  let mut dups = 0;
  for line in text.lines() {
    if line.trim() == "" { continue; }
    if seen.get(line).is_some() {
      dups += 1;
      continue;
    }
    seen.insert(line, true);
    let parts = line.split(" ");
    if parts.len() != 3 { malformed += 1; continue; }
    if parts[1] == "" || parts[2] == "" { malformed += 1; continue; }
    let Some(t) = parse_time(parts[0]) else { malformed += 1; continue; };
    evs.push(Ev { user: parts[1], page: parts[2], t: t });
  }
  let tail = "malformed " + malformed.to_str() + " duplicates " + dups.to_str();
  if evs.len() == 0 { return Ok(tail); }

  let mut counts: Map<Str, Int> = Map::new();
  for e in evs {
    let c = counts.get(e.page).unwrap_or(0);
    counts.insert(e.page, c + 1);
  }
  evs.sort_by(|a, b| a.user < b.user || (a.user == b.user && a.t < b.t));

  let mut lines: List<Str> = [];
  let mut durations: List<Int> = [];
  let mut have = false;
  let mut cur = "";
  let mut sessions = 0;
  let mut events = 0;
  let mut longest = 0;
  let mut start = 0;
  let mut prev = 0;
  let mut pages: Map<Str, Bool> = Map::new();
  for e in evs {
    if have && e.user != cur {
      durations.push(prev - start);
      lines.push(line_for(cur, sessions, events, longest, pages.len()));
      have = false;
    }
    if !have {
      cur = e.user;
      sessions = 1;
      events = 1;
      longest = 0;
      start = e.t;
      prev = e.t;
      pages = Map::new();
      pages.insert(e.page, true);
      have = true;
    } else {
      if e.t - prev > 1800 {
        durations.push(prev - start);
        sessions += 1;
        start = e.t;
      }
      events += 1;
      prev = e.t;
      let d = e.t - start;
      if d > longest { longest = d; }
      pages.insert(e.page, true);
    }
  }
  durations.push(prev - start);
  lines.push(line_for(cur, sessions, events, longest, pages.len()));

  durations.sort();
  let med = durations[(durations.len() - 1) / 2];
  lines.push("median " + med.to_str());

  let mut pcs: List<PC> = [];
  for k in counts.keys() {
    pcs.push(PC { page: k, n: counts.get(k).unwrap_or(0) });
  }
  pcs.sort_by(|a, b| a.n > b.n || (a.n == b.n && a.page < b.page));
  let mut tops: List<Str> = [];
  let mut i = 0;
  while i < pcs.len() && i < 3 {
    tops.push(pcs[i].page + " (" + pcs[i].n.to_str() + ")");
    i += 1;
  }
  lines.push("top: " + tops.join(", "));
  lines.push(tail);
  Ok(lines.join("\n"))
}

