struct Rec { fields: List<Str>, bad: Bool }
struct Row { region: Str, product: Str, qty: Int, cents: Int }
struct Agg { rev: Int, items: Int, prods: Map<Str, Int> }

fn parse(data: Bytes) -> List<Rec> {
  let n = data.len();
  let mut recs: List<Rec> = [];
  let mut fields: List<Str> = [];
  let mut cur = "".to_bytes();
  let mut in_q = false;
  let mut quoted = false;
  let mut closed = false;
  let mut bad = false;
  let mut i = 0;
  while i < n {
    let c = data[i];
    if c == 13 && !in_q && i + 1 < n && data[i + 1] == 10 {
      i += 1;
      continue;
    }
    if in_q {
      if c == 34 {
        if i + 1 < n && data[i + 1] == 34 {
          cur.push(34);
          i += 1;
        } else {
          in_q = false;
          closed = true;
        }
      } else {
        cur.push(c);
      }
    } else if c == 34 {
      if cur.len() == 0 && !quoted {
        in_q = true;
        quoted = true;
      } else {
        bad = true;
      }
    } else if c == 44 {
      fields.push(cur.to_str());
      cur = "".to_bytes();
      quoted = false;
      closed = false;
    } else if c == 10 {
      if !(fields.len() == 0 && cur.len() == 0 && !quoted) {
        fields.push(cur.to_str());
        recs.push(Rec { fields: fields, bad: bad });
      }
      fields = [];
      cur = "".to_bytes();
      quoted = false;
      closed = false;
      bad = false;
    } else {
      if closed {
        bad = true;
      } else {
        cur.push(c);
      }
    }
    i += 1;
  }
  if in_q {
    fields.push(cur.to_str());
    recs.push(Rec { fields: fields, bad: true });
  } else if !(fields.len() == 0 && cur.len() == 0 && !quoted) {
    fields.push(cur.to_str());
    recs.push(Rec { fields: fields, bad: bad });
  }
  recs
}

fn is_digits(s: Str) -> Bool {
  if s.len() == 0 { return false; }
  for b in s.to_bytes() {
    if b < 48 || b > 57 { return false; }
  }
  true
}

fn validate(f: List<Str>) -> Option<Row> {
  if f.len() != 5 { return None; }
  if f[0].len() == 0 || f[1].len() == 0 { return None; }
  let s = f[2];
  let body = if s.starts_with("-") { s.slice(1, s.len()) } else { s };
  if !is_digits(body) { return None; }
  let qty = s.parse_int()?;
  let parts = f[3].split(".");
  if parts.len() > 2 { return None; }
  if !is_digits(parts[0]) { return None; }
  let whole = parts[0].parse_int()?;
  let mut frac = 0;
  if parts.len() == 2 {
    let p = parts[1];
    if !is_digits(p) { return None; }
    if p.len() > 2 { return None; }
    let v = p.parse_int()?;
    frac = if p.len() == 1 { v * 10 } else { v };
  }
  Some(Row { region: f[0], product: f[1], qty: qty, cents: whole * 100 + frac })
}

fn fmt(c: Int) -> Str {
  let a = if c < 0 { -c } else { c };
  let whole = a / 100;
  let frac = a % 100;
  let sign = if c < 0 { "-" } else { "" };
  let pad = if frac < 10 { "0" } else { "" };
  sign + whole.to_str() + "." + pad + frac.to_str()
}

fn enc(s: Str) -> Str {
  if s.contains(",") || s.contains("\"") || s.contains("\r") || s.contains("\n") {
    "\"" + s.replace("\"", "\"\"") + "\""
  } else {
    s
  }
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let data = input.read("sales.csv")?;
  let recs = parse(data);
  let mut clean = "region,product,qty,price,note\n";
  let mut aggs: Map<Str, Agg> = Map::new();
  let mut bads: List<Str> = [];
  let mut total = 0;
  let mut idx = 1;
  while idx < recs.len() {
    total += 1;
    let r = recs[idx];
    let mut ok = false;
    if !r.bad {
      if let Some(row) = validate(r.fields) {
        ok = true;
        clean = clean + enc(row.region) + "," + enc(row.product) + "," + r.fields[2] + "," + fmt(row.cents) + "," + enc(r.fields[4]) + "\n";
        let rev = row.qty * row.cents;
        let mut a = match aggs.get(row.region) {
          Some(x) => x,
          None => { let m: Map<Str, Int> = Map::new(); Agg { rev: 0, items: 0, prods: m } },
        };
        a.rev = a.rev + rev;
        a.items = a.items + row.qty;
        let old = a.prods.get(row.product).unwrap_or(0);
        a.prods.insert(row.product, old + rev);
        aggs.insert(row.region, a);
      }
    }
    if !ok { bads.push(total.to_str()); }
    idx += 1;
  }
  out.create("clean.csv", clean.to_bytes())?;
  let mut lines: List<Str> = [];
  for region in aggs.keys() {
    let a = aggs.get(region).unwrap_or(Agg { rev: 0, items: 0, prods: Map::new() });
    let mut best = "";
    let mut best_rev = 0;
    let mut first = true;
    for p in a.prods.keys() {
      let v = a.prods.get(p).unwrap_or(0);
      if first || v > best_rev {
        best = p;
        best_rev = v;
        first = false;
      }
    }
    lines.push(region + " revenue " + fmt(a.rev) + " items " + a.items.to_str() + " top " + best);
  }
  let tail = if bads.len() == 0 {
    "records " + total.to_str() + " bad 0"
  } else {
    "records " + total.to_str() + " bad " + bads.len().to_str() + ": " + bads.join(", ")
  };
  lines.push(tail);
  Ok(lines.join("\n"))
}

fn is_w(b: Int) -> Bool {
  b >= 128 || (b >= 48 && b <= 57) || (b >= 65 && b <= 90) || (b >= 97 && b <= 122)
}

fn words(text: Bytes) -> List<Str> {
  let mut seen: Map<Str, Bool> = Map::new();
  let mut cur = "".to_bytes();
  for b in text {
    if is_w(b) {
      cur.push(b);
    } else {
      if cur.len() > 0 {
        seen.insert(cur.to_str().to_lowercase(), true);
        cur = "".to_bytes();
      }
    }
  }
  if cur.len() > 0 {
    seen.insert(cur.to_str().to_lowercase(), true);
  }
  seen.keys()
}

fn walk(d: Dir, base: Str) -> Result<List<Str>, IoErr> {
  let dirpath = if base.len() == 0 { "" } else { base.slice(0, base.len() - 1) };
  let names = d.list(dirpath)?;
  let mut out: List<Str> = [];
  for n in names {
    if n.ends_with("/") {
      let sub = walk(d, base + n)?;
      for s in sub { out.push(s); }
    } else {
      out.push(base + n);
    }
  }
  Ok(out)
}

fn drop_words(index: Kv, path: Str) -> Result<(), KvErr> {
  let old = index.get("d/" + path)?;
  if let Some(b) = old {
    for w in b.to_str().split("\n") {
      if w.len() > 0 {
        index.delete("w/" + w + "/" + path)?;
      }
    }
  }
  index.delete("d/" + path)?;
  Ok(())
}

fn put_words(index: Kv, path: Str, ws: List<Str>) -> Result<(), KvErr> {
  for w in ws {
    index.set("w/" + w + "/" + path, "1".to_bytes())?;
  }
  index.set("d/" + path, ws.join("\n").to_bytes())
}

fn paths_for(index: Kv, w: Str) -> Result<List<Str>, KvErr> {
  let pre = "w/" + w + "/";
  let ks = index.keys(pre)?;
  let mut out: List<Str> = [];
  for k in ks { out.push(k.slice(pre.len(), k.len())); }
  Ok(out)
}

fn run(docs: Dir, queries: Dir, index: Kv) -> Result<Str, Str> {
  let mut files = walk(docs, "").map_err(|e| "list failed")?;
  files.sort();
  let mut status: Map<Str, Str> = Map::new();
  let mut cur: Map<Str, Bool> = Map::new();
  let mut unchanged = 0;
  for p in files {
    cur.insert(p, true);
    let bytes = docs.read(p).map_err(|e| "read failed: " + p)?;
    let h = bytes.sha256().to_hex();
    let old = index.get("f/" + p).map_err(|e| "kv failed")?;
    let state = match old {
      None => 1,
      Some(b) => if b.to_str() == h { 0 } else { 2 },
    };
    if state == 0 {
      unchanged = unchanged + 1;
    } else {
      drop_words(index, p).map_err(|e| "kv failed")?;
      put_words(index, p, words(bytes)).map_err(|e| "kv failed")?;
      index.set("f/" + p, h.to_bytes()).map_err(|e| "kv failed")?;
      status.insert(p, if state == 1 { "added" } else { "changed" });
    }
  }
  let olds = index.keys("f/").map_err(|e| "kv failed")?;
  for k in olds {
    let p = k.slice(2, k.len());
    if cur.get(p).is_none() {
      drop_words(index, p).map_err(|e| "kv failed")?;
      index.delete("f/" + p).map_err(|e| "kv failed")?;
      status.insert(p, "removed");
    }
  }
  let mut out = "";
  for p in status.keys() {
    out = out + status.get(p).unwrap_or("") + " " + p + "\n";
  }
  out = out + "unchanged " + unchanged.to_str() + "\n";

  let text = queries.read("queries.txt").map_err(|e| "read failed: queries.txt")?.to_str();
  for line in text.lines() {
    if line.trim().len() == 0 { continue; }
    let ws = words(line.to_bytes());
    let mut matches: List<Str> = [];
    if ws.len() == 0 {
      matches = cur.keys();
    } else {
      matches = paths_for(index, ws[0]).map_err(|e| "kv failed")?;
      for i in 1..ws.len() {
        let other = paths_for(index, ws[i]).map_err(|e| "kv failed")?;
        let mut next: List<Str> = [];
        for p in matches {
          if other.contains(p) { next.push(p); }
        }
        matches = next;
      }
    }
    if matches.len() == 0 {
      out = out + line + ": none\n";
    } else {
      out = out + line + ": " + matches.join(", ") + "\n";
    }
  }
  Ok(out)
}

fn main(docs: Dir, queries: Dir, index: Kv) -> Result<Str, Str> {
  run(docs, queries, index)
}

struct Change { op: Str, sku: Str, name: Str, qty: Int, version: Int }

fn parse_change(j: Json) -> Option<Change> {
  let op = j.get("op").and_then(|x| x.as_str())?;
  let sku = j.get("sku").and_then(|x| x.as_str())?;
  let version = j.get("version").and_then(|x| x.as_int())?;
  if op == "upsert" {
    let name = j.get("name").and_then(|x| x.as_str())?;
    let qty = j.get("qty").and_then(|x| x.as_int())?;
    Some(Change { op: op, sku: sku, name: name, qty: qty, version: version })
  } else if op == "delete" {
    Some(Change { op: op, sku: sku, name: "", qty: 0, version: version })
  } else {
    None
  }
}

fn db_version(db: Db, sku: Str) -> Result<Option<Int>, DbErr> {
  let rows = db.query("SELECT version FROM versions WHERE sku = ?", [SqlValue::Text(sku)])?;
  if rows.len() == 0 { return Ok(None); }
  match rows[0][0] {
    SqlValue::Int(v) => Ok(Some(v)),
    _ => Ok(None),
  }
}

fn cell(v: SqlValue) -> Str {
  match v {
    SqlValue::Int(i) => i.to_str(),
    SqlValue::Text(t) => t,
    SqlValue::Float(f) => f.to_str(),
    SqlValue::Blob(_) => "",
    SqlValue::Null => "",
  }
}

fn main(api: Http, db: Db) -> Result<Str, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS versions (sku TEXT PRIMARY KEY, version INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT NOT NULL)", [])?;

  let crow = db.query("SELECT v FROM meta WHERE k = 'cursor'", [])?;
  let mut cursor = "0";
  if crow.len() > 0 {
    match crow[0][0] {
      SqlValue::Text(t) => cursor = t,
      _ => {}
    }
  }

  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut end = "complete";

  loop {
    let path = "/changes?cursor=" + cursor;
    let Ok(resp) = api.send("GET", path, [], "".to_bytes(), 0) else {
      end = "stopped at " + cursor + " (no response)";
      break;
    };
    if resp.status != 200 {
      end = "stopped at " + cursor + " (status " + resp.status.to_str() + ")";
      break;
    }
    let body = resp.body.to_str();
    let Ok(doc) = body.parse_json() else {
      end = "stopped at " + cursor + " (invalid page)";
      break;
    };
    let Some(changes) = doc.get("changes").and_then(|x| x.as_list()) else {
      end = "stopped at " + cursor + " (invalid page)";
      break;
    };
    let mut next: Option<Str> = None;
    let mut bad = false;
    match doc.get("next") {
      None => {}
      Some(Json::Null) => {}
      Some(Json::Str(s)) => next = Some(s),
      Some(Json::Num(n)) => next = Some(n.to_str()),
      _ => bad = true,
    }
    if bad {
      end = "stopped at " + cursor + " (invalid page)";
      break;
    }

    let mut stmts: List<Str> = [];
    let mut params: List<List<SqlValue>> = [];
    let mut vers: HashMap<Str, Int> = HashMap::new();
    let mut a = 0;
    let mut s = 0;
    let mut inv = 0;
    for j in changes {
      let Some(c) = parse_change(j) else {
        inv += 1;
        continue;
      };
      let cur = match vers.get(c.sku) {
        Some(v) => Some(v),
        None => db_version(db, c.sku)?,
      };
      let is_stale = match cur {
        Some(v) => c.version <= v,
        None => false,
      };
      if is_stale {
        s += 1;
        continue;
      }
      if c.op == "upsert" {
        stmts.push("INSERT INTO items(sku, name, qty) VALUES(?, ?, ?) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty");
        params.push([SqlValue::Text(c.sku), SqlValue::Text(c.name), SqlValue::Int(c.qty)]);
      } else {
        stmts.push("DELETE FROM items WHERE sku = ?");
        params.push([SqlValue::Text(c.sku)]);
      }
      stmts.push("INSERT INTO versions(sku, version) VALUES(?, ?) ON CONFLICT(sku) DO UPDATE SET version = excluded.version");
      params.push([SqlValue::Text(c.sku), SqlValue::Int(c.version)]);
      vers.insert(c.sku, c.version);
      a += 1;
    }

    let store = match next {
      Some(n) => n,
      None => cursor,
    };
    stmts.push("INSERT INTO meta(k, v) VALUES('cursor', ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v");
    params.push([SqlValue::Text(store)]);
    let Ok(_) = db.transaction(stmts, params) else {
      end = "stopped at " + cursor + " (no response)";
      break;
    };

    pages += 1;
    applied += a;
    stale += s;
    invalid += inv;
    match next {
      Some(n) => cursor = n,
      None => {
        end = "complete";
        break;
      }
    }
  }

  let mut lines: List<Str> = [];
  lines.push("pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str() + " invalid " + invalid.to_str());
  lines.push(end);
  let rows = db.query("SELECT sku, qty, name FROM items ORDER BY sku", [])?;
  for r in rows {
    lines.push(cell(r[0]) + " " + cell(r[1]) + " " + cell(r[2]));
  }
  Ok(lines.join("\n"))
}

struct Job { id: Str, pri: Int, due: Int, att: Int, st: Str }

fn save_job(queue: Kv, j: Job) -> Result<(), KvErr> {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("p", Json::Num(j.pri));
  m.insert("due", Json::Num(j.due));
  m.insert("att", Json::Num(j.att));
  m.insert("st", Json::Str(j.st));
  queue.set("job/" + j.id, Json::Obj(m).to_json().to_bytes())
}

fn load_job(queue: Kv, key: Str) -> Result<Option<Job>, KvErr> {
  let Some(b) = queue.get(key)? else { return Ok(None); };
  let Ok(doc) = b.to_str().parse_json() else { return Ok(None); };
  Ok(Some(Job {
    id: key.slice(4, key.len()),
    pri: doc.get("p").and_then(|j| j.as_int()).unwrap_or(0),
    due: doc.get("due").and_then(|j| j.as_int()).unwrap_or(0),
    att: doc.get("att").and_then(|j| j.as_int()).unwrap_or(0),
    st: doc.get("st").and_then(|j| j.as_str()).unwrap_or("pending"),
  }))
}

fn load_all(queue: Kv) -> Result<List<Job>, KvErr> {
  let keys = queue.keys("job/")?;
  let mut out: List<Job> = [];
  for k in keys {
    let r = load_job(queue, k)?;
    if let Some(j) = r { out.push(j); }
  }
  Ok(out)
}

fn less(a: Job, b: Job) -> Bool {
  if a.pri != b.pri { return a.pri > b.pri; }
  if a.due != b.due { return a.due < b.due; }
  a.id < b.id
}

fn is_ok(script: Json, id: Str, att: Int) -> Bool {
  let list = script.get(id).and_then(|j| j.as_list()).unwrap_or([]);
  if list.len() == 0 { return true; }
  let i = if att < list.len() { att } else { list.len() - 1 };
  list[i].as_str().unwrap_or("ok") == "ok"
}

fn read_text(d: Dir, name: Str) -> Str {
  match d.read(name) {
    Ok(b) => b.to_str(),
    Err(_) => "",
  }
}

fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, KvErr> {
  let now = clock.now_ms();
  let mut out: List<Str> = [];

  let lines = read_text(input, "enqueue.jsonl").lines();
  for i in 0..lines.len() {
    let line = lines[i].trim();
    if line.len() == 0 { continue; }
    let bad = "invalid line " + (i + 1).to_str();
    let Ok(doc) = line.parse_json() else { out.push(bad); continue; };
    let Some(id) = doc.get("id").and_then(|j| j.as_str()) else { out.push(bad); continue; };
    let Some(pri) = doc.get("priority").and_then(|j| j.as_int()) else { out.push(bad); continue; };
    let existing = queue.get("job/" + id)?;
    if existing.is_some() {
      out.push("duplicate " + id);
      continue;
    }
    save_job(queue, Job { id: id, pri: pri, due: now, att: 0, st: "pending" })?;
  }

  let script = match read_text(input, "script.json").parse_json() {
    Ok(j) => j,
    Err(_) => Json::Null,
  };

  let all = load_all(queue)?;
  let mut ready: List<Job> = [];
  for j in all {
    if j.st == "pending" && j.due <= now { ready.push(j); }
  }
  ready.sort_by(less);
  let mut n = 0;
  while n < 5 && n < ready.len() {
    let j = ready[n];
    n += 1;
    if is_ok(script, j.id, j.att) {
      save_job(queue, Job { st: "done", att: j.att + 1, ..j })?;
      out.push("done " + j.id);
    } else if j.att + 1 >= 4 {
      save_job(queue, Job { st: "dead", att: j.att + 1, ..j })?;
      out.push("dead " + j.id);
    } else {
      let mut secs = 60;
      for _k in 0..j.att { secs = secs * 2; }
      save_job(queue, Job { due: now + secs * 1000, att: j.att + 1, ..j })?;
      out.push("retry " + j.id + " in " + secs.to_str());
    }
  }

  let fin = load_all(queue)?;
  let mut p = 0;
  let mut d = 0;
  let mut x = 0;
  for j in fin {
    if j.st == "done" { d += 1; }
    else if j.st == "dead" { x += 1; }
    else { p += 1; }
  }
  out.push("pending " + p.to_str() + " done " + d.to_str() + " dead " + x.to_str());
  Ok(out.join("\n"))
}

struct Tok { kind: Str, text: Str }
struct Node { kind: Str, ival: Int, name: Str, kids: List<Node> }
struct PR { node: Node, pos: Int }
struct Stmt { is_let: Bool, name: Str, node: Node }

const MAXI: Int = 9223372036854775807;

fn min_int() -> Int { -9223372036854775807 - 1 }

fn mk(kind: Str, ival: Int, name: Str, kids: List<Node>) -> Node {
  Node { kind: kind, ival: ival, name: name, kids: kids }
}

fn is_digit(c: Str) -> Bool { c >= "0" && c <= "9" }
fn is_alpha(c: Str) -> Bool {
  (c >= "a" && c <= "z") || (c >= "A" && c <= "Z") || c == "_"
}

fn tokenize(line: Str) -> Option<List<Tok>> {
  let cs = line.chars();
  let mut out: List<Tok> = [];
  let mut i = 0;
  while i < cs.len() {
    let c = cs[i];
    if c == " " || c == "\t" || c == "\r" {
      i += 1;
    } else if is_digit(c) {
      let mut j = i;
      let mut s = "";
      while j < cs.len() && is_digit(cs[j]) {
        s = s + cs[j];
        j += 1;
      }
      out.push(Tok { kind: "int", text: s });
      i = j;
    } else if is_alpha(c) {
      let mut j = i;
      let mut s = "";
      while j < cs.len() && (is_alpha(cs[j]) || is_digit(cs[j])) {
        s = s + cs[j];
        j += 1;
      }
      out.push(Tok { kind: "name", text: s });
      i = j;
    } else if "+-*/%^(),=".contains(c) {
      out.push(Tok { kind: "op", text: c });
      i += 1;
    } else {
      return None;
    }
  }
  Some(out)
}

fn at_op(t: List<Tok>, pos: Int, s: Str) -> Bool {
  pos < t.len() && t[pos].kind == "op" && t[pos].text == s
}

fn int_node(text: Str) -> Node {
  let mut v = 0;
  for c in text.chars() {
    let d = c.parse_int().unwrap_or(0);
    if v > (MAXI - d) / 10 {
      return mk("ovf", 0, "", []);
    }
    v = v * 10 + d;
  }
  mk("num", v, "", [])
}

fn parse_atom(t: List<Tok>, pos: Int) -> Option<PR> {
  if pos >= t.len() { return None; }
  let tok = t[pos];
  if tok.kind == "int" {
    return Some(PR { node: int_node(tok.text), pos: pos + 1 });
  }
  if tok.kind == "name" {
    if at_op(t, pos + 1, "(") {
      let mut kids: List<Node> = [];
      let r = parse_expr(t, pos + 2)?;
      kids.push(r.node);
      let mut p = r.pos;
      while at_op(t, p, ",") {
        let r2 = parse_expr(t, p + 1)?;
        kids.push(r2.node);
        p = r2.pos;
      }
      if !at_op(t, p, ")") { return None; }
      return Some(PR { node: mk("call", 0, tok.text, kids), pos: p + 1 });
    }
    return Some(PR { node: mk("var", 0, tok.text, []), pos: pos + 1 });
  }
  if tok.kind == "op" && tok.text == "(" {
    let r = parse_expr(t, pos + 1)?;
    if !at_op(t, r.pos, ")") { return None; }
    return Some(PR { node: r.node, pos: r.pos + 1 });
  }
  None
}

fn parse_power(t: List<Tok>, pos: Int) -> Option<PR> {
  let a = parse_atom(t, pos)?;
  if at_op(t, a.pos, "^") {
    let r = parse_factor(t, a.pos + 1)?;
    return Some(PR { node: mk("^", 0, "", [a.node, r.node]), pos: r.pos });
  }
  Some(a)
}

fn parse_factor(t: List<Tok>, pos: Int) -> Option<PR> {
  if at_op(t, pos, "-") {
    let r = parse_factor(t, pos + 1)?;
    return Some(PR { node: mk("neg", 0, "", [r.node]), pos: r.pos });
  }
  parse_power(t, pos)
}

fn parse_term(t: List<Tok>, pos0: Int) -> Option<PR> {
  let first = parse_factor(t, pos0)?;
  let mut node = first.node;
  let mut pos = first.pos;
  loop {
    if at_op(t, pos, "*") || at_op(t, pos, "/") || at_op(t, pos, "%") {
      let op = t[pos].text;
      let r = parse_factor(t, pos + 1)?;
      node = mk(op, 0, "", [node, r.node]);
      pos = r.pos;
    } else {
      break;
    }
  }
  Some(PR { node: node, pos: pos })
}

fn parse_expr(t: List<Tok>, pos0: Int) -> Option<PR> {
  let first = parse_term(t, pos0)?;
  let mut node = first.node;
  let mut pos = first.pos;
  loop {
    if at_op(t, pos, "+") || at_op(t, pos, "-") {
      let op = t[pos].text;
      let r = parse_term(t, pos + 1)?;
      node = mk(op, 0, "", [node, r.node]);
      pos = r.pos;
    } else {
      break;
    }
  }
  Some(PR { node: node, pos: pos })
}

fn parse_line(t: List<Tok>) -> Option<Stmt> {
  if t.len() == 0 { return None; }
  if t[0].kind == "name" && t[0].text == "let" {
    if t.len() < 3 { return None; }
    if t[1].kind != "name" { return None; }
    if !at_op(t, 2, "=") { return None; }
    let r = parse_expr(t, 3)?;
    if r.pos != t.len() { return None; }
    return Some(Stmt { is_let: true, name: t[1].text, node: r.node });
  }
  let r = parse_expr(t, 0)?;
  if r.pos != t.len() { return None; }
  Some(Stmt { is_let: false, name: "", node: r.node })
}

fn add(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a > MAXI - b { return Err("overflow"); }
  if b < 0 && a < min_int() - b { return Err("overflow"); }
  Ok(a + b)
}

fn sub(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a < min_int() + b { return Err("overflow"); }
  if b < 0 && a > MAXI + b { return Err("overflow"); }
  Ok(a - b)
}

fn mul(a: Int, b: Int) -> Result<Int, Str> {
  if a == 0 || b == 0 { return Ok(0); }
  if a == -1 {
    if b == min_int() { return Err("overflow"); }
    return Ok(-b);
  }
  if b == -1 {
    if a == min_int() { return Err("overflow"); }
    return Ok(-a);
  }
  if a > 0 && b > 0 {
    if a > MAXI / b { return Err("overflow"); }
  } else if a < 0 && b < 0 {
    if a < MAXI / b { return Err("overflow"); }
  } else if a > 0 && b < 0 {
    if a > min_int() / b { return Err("overflow"); }
  } else {
    if a < min_int() / b { return Err("overflow"); }
  }
  Ok(a * b)
}

fn power(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 { return Err("negative exponent"); }
  if a == 0 { return Ok(if b == 0 { 1 } else { 0 }); }
  if a == 1 { return Ok(1); }
  if a == -1 { return Ok(if b % 2 == 0 { 1 } else { -1 }); }
  if b > 63 { return Err("overflow"); }
  let mut r = 1;
  let mut k = 0;
  while k < b {
    r = mul(r, a)?;
    k += 1;
  }
  Ok(r)
}

fn eval(n: Node, vars: Map<Str, Int>) -> Result<Int, Str> {
  match n.kind {
    "num" => Ok(n.ival),
    "ovf" => Err("overflow"),
    "var" => match vars.get(n.name) {
      Some(v) => Ok(v),
      None => Err("unknown variable " + n.name),
    },
    "neg" => {
      let v = eval(n.kids[0], vars)?;
      if v == min_int() { Err("overflow") } else { Ok(-v) }
    }
    "call" => {
      if n.name != "min" && n.name != "max" && n.name != "abs" {
        return Err("unknown function " + n.name);
      }
      let want = if n.name == "abs" { 1 } else { 2 };
      if n.kids.len() != want {
        return Err("wrong number of arguments to " + n.name);
      }
      let a = eval(n.kids[0], vars)?;
      if n.name == "abs" {
        if a == min_int() { return Err("overflow"); }
        return Ok(if a < 0 { -a } else { a });
      }
      let b = eval(n.kids[1], vars)?;
      if n.name == "min" { Ok(a.min(b)) } else { Ok(a.max(b)) }
    }
    _ => {
      let a = eval(n.kids[0], vars)?;
      let b = eval(n.kids[1], vars)?;
      match n.kind {
        "+" => add(a, b),
        "-" => sub(a, b),
        "*" => mul(a, b),
        "/" => {
          if b == 0 { return Err("division by zero"); }
          if a == min_int() && b == -1 { return Err("overflow"); }
          Ok(a / b)
        }
        "%" => {
          if b == 0 { return Err("division by zero"); }
          if b == -1 { return Ok(0); }
          Ok(a % b)
        }
        _ => power(a, b),
      }
    }
  }
}

fn run_line(line: Str, vars: Map<Str, Int>) -> Str {
  let toks = match tokenize(line) {
    Some(t) => t,
    None => return "error: syntax error",
  };
  let st = match parse_line(toks) {
    Some(s) => s,
    None => return "error: syntax error",
  };
  match eval(st.node, vars) {
    Ok(v) => if st.is_let { st.name + " = " + v.to_str() } else { v.to_str() },
    Err(e) => "error: " + e,
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let mut vars: Map<Str, Int> = Map::new();
  let mut out = "";
  let mut n = 0;
  for raw in text.lines() {
    n += 1;
    let line = raw.trim();
    if line.len() == 0 { continue; }
    let toks = tokenize(line);
    let mut res = "error: syntax error";
    let mut bind_name = "";
    let mut bind_val = 0;
    let mut do_bind = false;
    if let Some(tk) = toks {
      if let Some(st) = parse_line(tk) {
        match eval(st.node, vars) {
          Ok(v) => {
            if st.is_let {
              res = st.name + " = " + v.to_str();
              bind_name = st.name;
              bind_val = v;
              do_bind = true;
            } else {
              res = v.to_str();
            }
          }
          Err(e) => { res = "error: " + e; }
        }
      }
    }
    if do_bind { vars.insert(bind_name, bind_val); }
    out = out + n.to_str() + ": " + res + "\n";
  }
  Ok(out)
}

struct Resp { status: Int, body: Str }

fn resp(status: Int, body: Json) -> Resp {
  Resp { status: status, body: body.to_json() }
}

fn status_resp(status: Int, key: Str, val: Str) -> Resp {
  let mut m: Map<Str, Json> = Map::new();
  m.insert(key, Json::Str(val));
  resp(status, Json::Obj(m))
}

fn err(status: Int, msg: Str) -> Resp {
  status_resp(status, "error", msg)
}

fn text(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn int(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn transition(state: Str, typ: Str) -> Str {
  match typ {
    "subscription.created" => if state == "none" { "created" } else { "" },
    "subscription.activated" => if state == "created" || state == "past_due" { "active" } else { "" },
    "payment.failed" => if state == "active" { "past_due" } else { "" },
    "subscription.canceled" => if state == "created" || state == "active" || state == "past_due" { "canceled" } else { "" },
    _ => "",
  }
}

fn init(db: Db) -> Result<Int, DbErr> {
  db.transaction(
    ["CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, sub TEXT NOT NULL, seq INTEGER NOT NULL, type TEXT NOT NULL, applied INTEGER NOT NULL)",
     "CREATE INDEX IF NOT EXISTS ev_sub ON events(sub, seq)",
     "CREATE TABLE IF NOT EXISTS subs(id TEXT PRIMARY KEY, state TEXT NOT NULL, seq INTEGER NOT NULL, history TEXT NOT NULL)"],
    [[], [], []])
}

fn get_sub(db: Db, id: Str) -> Result<Option<List<SqlValue>>, DbErr> {
  let rows = db.query("SELECT state, seq, history FROM subs WHERE id = ?", [SqlValue::Text(id)])?;
  if rows.len() == 0 { Ok(None) } else { Ok(Some(rows[0])) }
}

fn find_sig(req: Incoming) -> Option<Str> {
  let names = req.header_names();
  let values = req.header_values();
  for i in 0..names.len() {
    if names[i] == "x-signature" { return Some(values[i]); }
  }
  None
}

fn webhook(req: Incoming, db: Db, secrets: Dir, log: Log) -> Result<Resp, DbErr> {
  let raw = match secrets.read("webhook.key") {
    Ok(b) => b.to_str(),
    Err(_) => return Ok(err(500, "no secret")),
  };
  let key = raw.strip_suffix("\n").unwrap_or(raw);
  let body = req.body();
  let mut msg = key.to_bytes();
  msg.extend(".".to_bytes());
  msg.extend(body);
  let expected = "sha256=" + msg.sha256().to_hex();
  let ok = match find_sig(req) {
    Some(s) => s.ct_eq(expected),
    None => false,
  };
  if !ok {
    let _l = log.write("rejected signature");
    return Ok(err(401, "bad signature"));
  }
  let bad = err(400, "invalid event");
  let j = match body.to_str().parse_json() {
    Ok(j) => j,
    Err(_) => return Ok(bad),
  };
  if j.as_map().is_none() { return Ok(bad); }
  let Some(eid) = j.get("id").and_then(|x| x.as_str()) else { return Ok(bad); };
  let Some(typ) = j.get("type").and_then(|x| x.as_str()) else { return Ok(bad); };
  let Some(sub) = j.get("subscription").and_then(|x| x.as_str()) else { return Ok(bad); };
  let Some(seq) = j.get("seq").and_then(|x| x.as_int()) else { return Ok(bad); };
  if seq < 1 { return Ok(bad); }
  if typ != "subscription.created" && typ != "subscription.activated" && typ != "payment.failed" && typ != "subscription.canceled" {
    return Ok(bad);
  }
  init(db)?;
  match db.exec("INSERT INTO events(id, sub, seq, type, applied) VALUES(?, ?, ?, ?, 0)",
      [SqlValue::Text(eid), SqlValue::Text(sub), SqlValue::Int(seq), SqlValue::Text(typ)]) {
    Err(DbErr::Constraint(_)) => return Ok(status_resp(200, "status", "duplicate")),
    Err(e) => return Err(e),
    Ok(_) => {},
  }
  let mut state = "none";
  let mut last = 0;
  let mut hist = "";
  match get_sub(db, sub)? {
    Some(row) => {
      state = text(row[0]);
      last = int(row[1]);
      hist = text(row[2]);
    },
    None => {},
  }
  if seq <= last {
    db.exec("UPDATE events SET applied = 2 WHERE id = ?", [SqlValue::Text(eid)])?;
    return Ok(status_resp(200, "status", "stale"));
  }
  if seq > last + 1 {
    return Ok(status_resp(202, "status", "queued"));
  }
  let mut k = 0;
  loop {
    let rows = db.query("SELECT id, type FROM events WHERE sub = ? AND seq = ? AND applied = 0 LIMIT 1",
      [SqlValue::Text(sub), SqlValue::Int(last + 1)])?;
    if rows.len() == 0 { break; }
    let id2 = text(rows[0][0]);
    let t2 = text(rows[0][1]);
    let ns = transition(state, t2);
    if ns == "" {
      let _l = log.write("invalid transition " + id2);
    } else {
      state = ns;
      if hist == "" { hist = ns; } else { hist = hist + "," + ns; }
    }
    last += 1;
    k += 1;
    db.transaction(
      ["INSERT OR REPLACE INTO subs(id, state, seq, history) VALUES(?, ?, ?, ?)",
       "UPDATE events SET applied = 1 WHERE id = ?"],
      [[SqlValue::Text(sub), SqlValue::Text(state), SqlValue::Int(last), SqlValue::Text(hist)],
       [SqlValue::Text(id2)]])?;
  }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("status", Json::Str("applied"));
  m.insert("applied", Json::Num(k));
  Ok(resp(200, Json::Obj(m)))
}

fn get_subscription(db: Db, id: Str) -> Result<Resp, DbErr> {
  init(db)?;
  match get_sub(db, id)? {
    None => Ok(err(404, "not found")),
    Some(row) => {
      let hist = text(row[2]);
      let mut items: List<Json> = [];
      if hist != "" {
        items = hist.split(",").map(|s| Json::Str(s));
      }
      let mut m: Map<Str, Json> = Map::new();
      m.insert("id", Json::Str(id));
      m.insert("state", Json::Str(text(row[0])));
      m.insert("seq", Json::Num(int(row[1])));
      m.insert("history", Json::Arr(items));
      Ok(resp(200, Json::Obj(m)))
    },
  }
}

fn handle(req: Incoming, db: Db, secrets: Dir, log: Log) -> Result<Resp, DbErr> {
  let method = req.method();
  let path = req.target().split("?")[0];
  if method == "POST" && path == "/webhooks" {
    return webhook(req, db, secrets, log);
  }
  if method == "GET" {
    if let Some(id) = path.strip_prefix("/subscriptions/") {
      if id != "" { return get_subscription(db, id); }
    }
  }
  Ok(err(404, "not found"))
}

fn main(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<Str, WebErr> {
  let r = match handle(req, db, secrets, log) {
    Ok(r) => r,
    Err(_) => err(500, "internal error"),
  };
  res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes())?;
  Ok("done")
}
